use anyhow::Result;
use canon::ir::CanonIR;

pub mod derive;
pub mod graph;
pub mod solver;

pub fn canon_analyze(ir: &mut CanonIR) -> Result<()> {
    derive::derive(ir)?;
    solver::solve(ir)?;
    Ok(())
}

use crate::graph::{
    call_graph::CallGraphBuilder, cfg_graph::CfgGraphBuilder, macro_graph::MacroGraphBuilder, module_graph::ModuleGraphBuilder, name_graph::NameGraphBuilder, region_graph::RegionGraphBuilder,
    type_graph::TypeGraphBuilder, value_graph::ValueGraphBuilder,
};
use anyhow::Result;
use canon::csr_graph::CsrGraph;
use canon::node::CanonId;
use canon::CanonIR;
use canon::{edge::EdgeKind, id::NodeId};

pub fn derive(ir: &mut CanonIR) -> Result<()> {
    let v = ir.nodes.len();

    let mut module_b = ModuleGraphBuilder::new(v);
    let mut call_b = CallGraphBuilder::new(v);
    let mut name_b = NameGraphBuilder::new(v);
    let mut type_b = TypeGraphBuilder::new(v);
    let mut cfg_b = CfgGraphBuilder::new(v);
    let mut region_b = RegionGraphBuilder::new(v);
    let mut value_b = ValueGraphBuilder::new(v);
    let mut macro_b = MacroGraphBuilder::new(v);

    module_b.derive_from_ir(ir);
    call_b.derive_from_ir(ir);
    name_b.derive_from_ir(ir);
    type_b.derive_from_ir(ir);
    cfg_b.derive_from_ir(ir);
    region_b.derive_from_ir(ir);
    value_b.derive_from_ir(ir);
    macro_b.derive_from_ir(ir);

    ir.module_graph = merge_graph_edges(v, &ir.module_graph, module_b.edges());
    ir.call_graph = merge_graph_edges(v, &ir.call_graph, call_b.edges());
    ir.name_graph = merge_graph_edges(v, &ir.name_graph, name_b.edges());
    ir.type_graph = merge_graph_edges(v, &ir.type_graph, type_b.edges());
    ir.cfg_graph = merge_graph_edges(v, &ir.cfg_graph, cfg_b.edges());
    ir.region_graph = merge_graph_edges(v, &ir.region_graph, region_b.edges());
    ir.value_graph = merge_graph_edges(v, &ir.value_graph, value_b.edges());
    ir.macro_graph = merge_graph_edges(v, &ir.macro_graph, macro_b.edges());

    Ok(())
}

fn merge_graph_edges(v: usize, existing: &CsrGraph<CanonId, EdgeKind>, derived: &[(u32, u32, EdgeKind)]) -> CsrGraph<CanonId, EdgeKind> {
    let mut edges: Vec<(u32, u32, EdgeKind)> = Vec::new();

    for src_idx in 0..existing.vertex_count() {
        let src_id = NodeId(src_idx as u32);
        for (dst_id, edge) in existing.neighbours(src_id) {
            edges.push((src_id.0, dst_id.0, edge.clone()));
        }
    }

    edges.extend(derived.iter().cloned());

    let node_ids: Vec<CanonId> = (0..v as u32).map(CanonId).collect();
    CsrGraph::from_edges(node_ids, edges)
}

//! Graph builders — Phase 1 of the analysis pipeline.
//!
//! Each sub-module constructs one CSR graph from the ModelIR node arena.
//! The builders produce raw edge lists (src, dst, EdgeKind) which
//! CsrGraph::from_edges compacts into CSR form.
//!
//! Variables:
//!   nodes    : &[Node]              — read-only node arena
//!   edges    : Vec<(u32,u32,ED)>   — raw edge list before CSR compaction
//!
//! Equation (all builders follow this pattern):
//!   for node in nodes:
//!     match node.kind -> emit (src, dst, EdgeKind) pairs
//!   CsrGraph::from_edges(node_ids, edges)

pub mod call_graph;
pub mod cfg_graph;
pub mod macro_graph;
pub mod module_graph;
pub mod name_graph;
pub mod region_graph;
pub mod type_graph;
pub mod value_graph;

use canon::csr_graph::CsrGraph;
use canon::edge::EdgeKind;
use canon::node::{CanonId, CanonNodeKind, CfgOp};
use canon::CanonIR;

pub struct CallGraphBuilder {
    v: usize,
    edges: Vec<(u32, u32, EdgeKind)>,
}

impl CallGraphBuilder {
    pub fn new(v: usize) -> Self {
        Self { v, edges: Vec::new() }
    }

    pub fn add_call(&mut self, caller: CanonId, callee: CanonId) {
        self.edges.push((caller.0, callee.0, EdgeKind::Calls));
    }

    pub fn derive_from_ir(&mut self, ir: &CanonIR) {
        for n in &ir.nodes {
            let CanonNodeKind::Fn { body: Some(body_id), .. } = &n.kind else {
                continue;
            };
            let CanonNodeKind::Body { blocks } = &ir.node(*body_id).kind else {
                continue;
            };
            for bb in blocks {
                let CanonNodeKind::BasicBlock { ops, .. } = &ir.node(*bb).kind else {
                    continue;
                };
                for op in ops {
                    if let CfgOp::Call { func, .. } = op {
                        self.add_call(n.id, *func);
                    }
                }
            }
        }
    }

    pub fn edges(&self) -> &[(u32, u32, EdgeKind)] {
        &self.edges
    }

    pub fn build(self) -> CsrGraph<CanonId, EdgeKind> {
        let node_ids: Vec<CanonId> = (0..self.v as u32).map(CanonId).collect();
        CsrGraph::from_edges(node_ids, self.edges)
    }
}

use canon::csr_graph::CsrGraph;
use canon::edge::EdgeKind;
use canon::node::{CanonId, CanonNodeKind, CfgOp};
use canon::CanonIR;

pub struct CfgGraphBuilder {
    v: usize,
    edges: Vec<(u32, u32, EdgeKind)>,
}

impl CfgGraphBuilder {
    pub fn new(v: usize) -> Self {
        Self { v, edges: Vec::new() }
    }

    pub fn add_cfg_edge(&mut self, src: CanonId, dst: CanonId) {
        self.edges.push((src.0, dst.0, EdgeKind::CfgEdge));
    }

    pub fn add_branch(&mut self, src: CanonId, dst: CanonId, label: String) {
        self.edges.push((src.0, dst.0, EdgeKind::CfgBranch { label }));
    }

    pub fn derive_from_ir(&mut self, ir: &CanonIR) {
        for n in &ir.nodes {
            let CanonNodeKind::Body { blocks } = &n.kind else {
                continue;
            };

            for (i, bb_id) in blocks.iter().enumerate() {
                let CanonNodeKind::BasicBlock { ops, next } = &ir.node(*bb_id).kind else {
                    continue;
                };

                if let Some(last) = ops.last() {
                    match last {
                        CfgOp::Goto(t) => {
                            if let Some(dst) = blocks.get(*t as usize).copied() {
                                self.add_cfg_edge(*bb_id, dst);
                            }
                        }
                        CfgOp::Branch { true_bb, false_bb, .. } => {
                            if let Some(t) = blocks.get(*true_bb as usize).copied() {
                                self.add_branch(*bb_id, t, "true".into());
                            }
                            if let Some(f) = blocks.get(*false_bb as usize).copied() {
                                self.add_branch(*bb_id, f, "false".into());
                            }
                        }
                        _ => {
                            if let Some(nx) = next.and_then(|ix| blocks.get(ix as usize).copied()) {
                                self.add_cfg_edge(*bb_id, nx);
                            } else if let Some(fallthrough) = blocks.get(i + 1).copied() {
                                self.add_cfg_edge(*bb_id, fallthrough);
                            }
                        }
                    }
                }
            }
        }
    }

    pub fn edges(&self) -> &[(u32, u32, EdgeKind)] {
        &self.edges
    }

    pub fn build(self) -> CsrGraph<CanonId, EdgeKind> {
        let node_ids: Vec<CanonId> = (0..self.v as u32).map(CanonId).collect();
        CsrGraph::from_edges(node_ids, self.edges)
    }
}

use canon::csr_graph::CsrGraph;
use canon::edge::EdgeKind;
use canon::node::{CanonId, CanonNodeKind};
use canon::CanonIR;

pub struct MacroGraphBuilder {
    v: usize,
    edges: Vec<(u32, u32, EdgeKind)>,
}

impl MacroGraphBuilder {
    pub fn new(v: usize) -> Self {
        Self { v, edges: Vec::new() }
    }

    pub fn add_expands(&mut self, src: CanonId, dst: CanonId) {
        self.edges.push((src.0, dst.0, EdgeKind::Expands));
    }

    pub fn derive_from_ir(&mut self, ir: &CanonIR) {
        let mut module_children: Vec<Vec<usize>> = vec![Vec::new(); ir.nodes.len()];
        for src in 0..ir.module_graph.vertex_count() {
            let src_id = canon::id::NodeId(src as u32);
            for (dst, edge) in ir.module_graph.neighbours(src_id) {
                if *edge == EdgeKind::Contains {
                    module_children[src].push(dst.index());
                }
            }
        }

        for (mid, children) in module_children.iter().enumerate() {
            let macros: Vec<CanonId> = children
                .iter()
                .filter_map(|&idx| match ir.nodes.get(idx).map(|n| &n.kind) {
                    Some(CanonNodeKind::MacroCall { .. }) => Some(CanonId(idx as u32)),
                    _ => None,
                })
                .collect();

            if macros.is_empty() {
                continue;
            }

            let expand_targets: Vec<CanonId> = children
                .iter()
                .filter_map(|&idx| match ir.nodes.get(idx).map(|n| &n.kind) {
                    Some(CanonNodeKind::MacroCall { .. }) | Some(CanonNodeKind::Module { .. }) | Some(CanonNodeKind::Crate { .. }) => None,
                    Some(_) => Some(CanonId(idx as u32)),
                    None => None,
                })
                .collect();

            let _ = mid;
            for m in &macros {
                for t in &expand_targets {
                    self.add_expands(*m, *t);
                }
            }
        }
    }

    pub fn edges(&self) -> &[(u32, u32, EdgeKind)] {
        &self.edges
    }

    pub fn build(self) -> CsrGraph<CanonId, EdgeKind> {
        let node_ids: Vec<CanonId> = (0..self.v as u32).map(CanonId).collect();
        CsrGraph::from_edges(node_ids, self.edges)
    }
}

use canon::csr_graph::CsrGraph;
use canon::edge::EdgeKind;
use canon::node::{CanonId, CanonNodeKind};
use canon::CanonIR;
use std::collections::HashMap;

pub struct ModuleGraphBuilder {
    v: usize,
    edges: Vec<(u32, u32, EdgeKind)>,
}

impl ModuleGraphBuilder {
    pub fn new(v: usize) -> Self {
        Self { v, edges: Vec::new() }
    }

    pub fn add_contains(&mut self, parent: CanonId, child: CanonId) {
        self.edges.push((parent.0, child.0, EdgeKind::Contains));
    }

    pub fn add_impl_for(&mut self, impl_node: CanonId, target: CanonId) {
        self.edges.push((impl_node.0, target.0, EdgeKind::ImplFor));
    }

    pub fn derive_from_ir(&mut self, ir: &CanonIR) {
        let crate_id = ir.nodes.iter().find_map(|n| if matches!(n.kind, CanonNodeKind::Crate { .. }) { Some(n.id) } else { None });

        let mut module_by_path: HashMap<String, CanonId> = HashMap::new();
        for n in &ir.nodes {
            if let CanonNodeKind::Module { path_id, .. } = &n.kind {
                module_by_path.insert(ir.lookup_path(*path_id).to_string(), n.id);
            }
        }

        for n in &ir.nodes {
            if let CanonNodeKind::Module { path_id, .. } = &n.kind {
                let path = ir.lookup_path(*path_id);
                let parent_path = path.rsplit_once("::").map(|(p, _)| p.to_string());
                if let Some(parent) = parent_path.and_then(|p| module_by_path.get(&p).copied()) {
                    self.add_contains(parent, n.id);
                } else if let Some(cid) = crate_id {
                    self.add_contains(cid, n.id);
                }
            }

            match &n.kind {
                CanonNodeKind::Trait { methods, .. } => {
                    for m in methods {
                        self.add_contains(n.id, *m);
                    }
                }
                CanonNodeKind::Struct { fields, .. } => {
                    for f in fields {
                        self.add_contains(n.id, *f);
                    }
                }
                CanonNodeKind::Enum { variants, .. } => {
                    for v in variants {
                        self.add_contains(n.id, *v);
                    }
                }
                CanonNodeKind::Body { blocks } => {
                    for bb in blocks {
                        self.add_contains(n.id, *bb);
                    }
                }
                CanonNodeKind::Impl { for_ty, .. } => {
                    self.add_impl_for(n.id, *for_ty);
                }
                _ => {}
            }
        }
    }

    pub fn edges(&self) -> &[(u32, u32, EdgeKind)] {
        &self.edges
    }

    pub fn build(self) -> CsrGraph<CanonId, EdgeKind> {
        let node_ids: Vec<CanonId> = (0..self.v as u32).map(CanonId).collect();
        CsrGraph::from_edges(node_ids, self.edges)
    }
}

use canon::csr_graph::CsrGraph;
use canon::edge::EdgeKind;
use canon::node::{CanonId, CanonNodeKind};
use canon::CanonIR;
use std::collections::HashMap;

pub struct NameGraphBuilder {
    v: usize,
    edges: Vec<(u32, u32, EdgeKind)>,
}

impl NameGraphBuilder {
    pub fn new(v: usize) -> Self {
        Self { v, edges: Vec::new() }
    }

    pub fn add_rename(&mut self, src: CanonId, dst: CanonId) {
        self.edges.push((src.0, dst.0, EdgeKind::Renames));
    }

    pub fn add_resolves(&mut self, src: CanonId, dst: CanonId) {
        self.edges.push((src.0, dst.0, EdgeKind::Resolves));
    }

    pub fn derive_from_ir(&mut self, ir: &CanonIR) {
        let resolver = Resolver::new(ir);

        for n in &ir.nodes {
            match &n.kind {
                CanonNodeKind::Use { path_id, alias, .. } => {
                    let path = ir.lookup_path(*path_id);
                    if let Some(target) = resolver.resolve_use(n.id, path) {
                        self.add_resolves(n.id, target);
                        if alias.is_some() {
                            self.add_rename(n.id, target);
                        }
                    }
                }
                CanonNodeKind::ExternCrate { name_id, alias: Some(_), .. } => {
                    let original = ir.lookup_name(*name_id);
                    if let Some(target) = resolver.resolve_unique_name(n.id, original) {
                        self.add_rename(n.id, target);
                    }
                }
                _ => {}
            }
        }
    }

    pub fn edges(&self) -> &[(u32, u32, EdgeKind)] {
        &self.edges
    }

    pub fn build(self) -> CsrGraph<CanonId, EdgeKind> {
        let node_ids: Vec<CanonId> = (0..self.v as u32).map(CanonId).collect();
        CsrGraph::from_edges(node_ids, self.edges)
    }
}

struct Resolver {
    by_mod_and_name: HashMap<(String, String), Vec<CanonId>>,
    by_name: HashMap<String, Vec<CanonId>>,
    module_path_of: Vec<Option<String>>,
    parent_of: Vec<Option<usize>>,
}

impl Resolver {
    fn new(ir: &CanonIR) -> Self {
        let mut module_path_of = vec![None; ir.nodes.len()];
        for n in &ir.nodes {
            if let CanonNodeKind::Module { path_id, .. } = &n.kind {
                module_path_of[n.id.0 as usize] = Some(ir.lookup_path(*path_id).to_string());
            }
        }

        let mut parent_of = vec![None; ir.nodes.len()];
        for src in 0..ir.module_graph.vertex_count() {
            let src_id = canon::id::NodeId(src as u32);
            for (dst, edge) in ir.module_graph.neighbours(src_id) {
                if *edge == EdgeKind::Contains && dst.index() < parent_of.len() {
                    parent_of[dst.index()] = Some(src);
                }
            }
        }

        let containing_module = |start: usize| -> Option<usize> {
            let mut cur = Some(start);
            while let Some(i) = cur {
                if matches!(ir.nodes.get(i).map(|n| &n.kind), Some(CanonNodeKind::Module { .. })) {
                    return Some(i);
                }
                cur = parent_of.get(i).and_then(|x| *x);
            }
            None
        };

        let mut by_mod_and_name: HashMap<(String, String), Vec<CanonId>> = HashMap::new();
        let mut by_name: HashMap<String, Vec<CanonId>> = HashMap::new();
        for n in &ir.nodes {
            let Some(name) = node_name(ir, &n.kind) else {
                continue;
            };
            by_name.entry(name.to_string()).or_default().push(n.id);

            if let Some(midx) = containing_module(n.id.0 as usize) {
                if let Some(Some(mod_path)) = module_path_of.get(midx) {
                    by_mod_and_name.entry((mod_path.clone(), name.to_string())).or_default().push(n.id);
                }
            }
        }

        Self { by_mod_and_name, by_name, module_path_of, parent_of }
    }

    fn resolve_unique_name(&self, skip: CanonId, name: &str) -> Option<CanonId> {
        let matches: Vec<CanonId> = self.by_name.get(name)?.iter().copied().filter(|id| *id != skip).collect();
        if matches.len() == 1 {
            Some(matches[0])
        } else {
            None
        }
    }

    fn resolve_use(&self, use_id: CanonId, path: &str) -> Option<CanonId> {
        if path.ends_with("::*") {
            return None;
        }

        let segments: Vec<&str> = path.split("::").filter(|s| !s.is_empty()).collect();
        if segments.is_empty() {
            return None;
        }

        let (base_mod, start_idx) = match segments.first().copied() {
            Some("crate") => (Some("crate".to_string()), 1usize),
            Some("self") => (self.containing_module_path(use_id), 1usize),
            Some("super") => (self.parent_module_path(use_id), 1usize),
            _ => (self.containing_module_path(use_id), 0usize),
        };

        let parts = &segments[start_idx..];
        if parts.is_empty() {
            return None;
        }

        let mut candidates: Vec<CanonId> = Vec::new();
        if parts.len() >= 2 {
            let target_name = parts[parts.len() - 1];
            let mod_suffix = parts[..parts.len() - 1].join("::");
            for module in self.candidate_module_paths(base_mod.as_deref(), &mod_suffix) {
                if let Some(ids) = self.by_mod_and_name.get(&(module, target_name.to_string())) {
                    candidates.extend(ids.iter().copied().filter(|id| *id != use_id));
                }
            }
        } else {
            let target_name = parts[0];
            if let Some(site_mod) = self.containing_module_path(use_id) {
                if let Some(ids) = self.by_mod_and_name.get(&(site_mod, target_name.to_string())) {
                    candidates.extend(ids.iter().copied().filter(|id| *id != use_id));
                }
            }
            if candidates.is_empty() {
                if let Some(ids) = self.by_mod_and_name.get(&("crate".to_string(), target_name.to_string())) {
                    candidates.extend(ids.iter().copied().filter(|id| *id != use_id));
                }
            }
        }

        dedup_ids(&mut candidates);
        if candidates.len() == 1 {
            return Some(candidates[0]);
        }

        // Strict fallback: only accept unique global symbol by exact name.
        let target_name = parts[parts.len() - 1];
        self.resolve_unique_name(use_id, target_name)
    }

    fn containing_module_path(&self, id: CanonId) -> Option<String> {
        let mut cur = Some(id.0 as usize);
        while let Some(i) = cur {
            if let Some(Some(path)) = self.module_path_of.get(i) {
                return Some(path.clone());
            }
            cur = self.parent_of.get(i).and_then(|x| *x);
        }
        None
    }

    fn parent_module_path(&self, id: CanonId) -> Option<String> {
        let here = self.containing_module_path(id)?;
        here.rsplit_once("::").map(|(p, _)| p.to_string())
    }

    fn candidate_module_paths(&self, base: Option<&str>, suffix: &str) -> Vec<String> {
        let Some(base) = base else {
            return vec![];
        };
        if suffix.is_empty() {
            return vec![base.to_string()];
        }
        if base == "crate" {
            vec![format!("crate::{}", suffix)]
        } else {
            vec![format!("{}::{}", base, suffix), format!("crate::{}", suffix)]
        }
    }
}

fn node_name<'a>(ir: &'a CanonIR, kind: &'a CanonNodeKind) -> Option<&'a str> {
    match kind {
        CanonNodeKind::Fn { name_id, .. }
        | CanonNodeKind::Struct { name_id, .. }
        | CanonNodeKind::Enum { name_id, .. }
        | CanonNodeKind::Trait { name_id, .. }
        | CanonNodeKind::TypeAlias { name_id, .. }
        | CanonNodeKind::TypeRef { name_id }
        | CanonNodeKind::Const { name_id, .. }
        | CanonNodeKind::Static { name_id, .. }
        | CanonNodeKind::ExternCrate { name_id, .. }
        | CanonNodeKind::Lifetime { name_id }
        | CanonNodeKind::GenericParam { name_id, .. }
        | CanonNodeKind::Param { name_id, .. }
        | CanonNodeKind::Variant { name_id, .. } => Some(ir.lookup_name(*name_id)),
        CanonNodeKind::Use { alias: Some(alias), .. } => Some(ir.lookup_name(*alias)),
        CanonNodeKind::Use { path_id, alias: None, .. } => Some(ir.lookup_path(*path_id)),
        _ => None,
    }
}

fn dedup_ids(ids: &mut Vec<CanonId>) {
    ids.sort_by_key(|id| id.0);
    ids.dedup_by_key(|id| id.0);
}

use canon::csr_graph::CsrGraph;
use canon::edge::EdgeKind;
use canon::node::{CanonId, CanonNodeKind};
use canon::CanonIR;

pub struct RegionGraphBuilder {
    v: usize,
    edges: Vec<(u32, u32, EdgeKind)>,
}

impl RegionGraphBuilder {
    pub fn new(v: usize) -> Self {
        Self { v, edges: Vec::new() }
    }

    pub fn add_outlives(&mut self, a: CanonId, b: CanonId) {
        self.edges.push((a.0, b.0, EdgeKind::Outlives));
    }

    pub fn derive_from_ir(&mut self, ir: &CanonIR) {
        for n in &ir.nodes {
            if let CanonNodeKind::GenericParam { bounds, is_lifetime, .. } = &n.kind {
                if !is_lifetime {
                    continue;
                }
                for b in bounds {
                    if matches!(ir.node(*b).kind, CanonNodeKind::Lifetime { .. }) {
                        self.add_outlives(n.id, *b);
                    }
                }
            }
        }
    }

    pub fn edges(&self) -> &[(u32, u32, EdgeKind)] {
        &self.edges
    }

    pub fn build(self) -> CsrGraph<CanonId, EdgeKind> {
        let node_ids: Vec<CanonId> = (0..self.v as u32).map(CanonId).collect();
        CsrGraph::from_edges(node_ids, self.edges)
    }
}

use canon::csr_graph::CsrGraph;
use canon::edge::EdgeKind;
use canon::node::{CanonId, CanonNodeKind};
use canon::CanonIR;

pub struct TypeGraphBuilder {
    v: usize,
    edges: Vec<(u32, u32, EdgeKind)>,
}

impl TypeGraphBuilder {
    pub fn new(v: usize) -> Self {
        Self { v, edges: Vec::new() }
    }

    pub fn add_type_of(&mut self, expr: CanonId, ty: CanonId) {
        self.edges.push((expr.0, ty.0, EdgeKind::TypeOf));
    }

    pub fn add_unifies(&mut self, a: CanonId, b: CanonId) {
        self.edges.push((a.0, b.0, EdgeKind::TypeUnifies));
    }

    pub fn derive_from_ir(&mut self, ir: &CanonIR) {
        for n in &ir.nodes {
            match &n.kind {
                CanonNodeKind::Fn { sig_id, .. } => {
                    if let CanonNodeKind::FnSig { params, ret, .. } = &ir.node(*sig_id).kind {
                        for p in params {
                            if let CanonNodeKind::Param { ty, .. } = &ir.node(*p).kind {
                                self.add_type_of(n.id, *ty);
                            }
                        }
                        self.add_type_of(n.id, *ret);
                    }
                }
                CanonNodeKind::Struct { fields, .. } => {
                    for f in fields {
                        if let CanonNodeKind::Field { ty, .. } = &ir.node(*f).kind {
                            self.add_type_of(*f, *ty);
                        }
                    }
                }
                CanonNodeKind::Field { ty, .. } | CanonNodeKind::Param { ty, .. } | CanonNodeKind::Const { ty, .. } | CanonNodeKind::Static { ty, .. } | CanonNodeKind::TypeAlias { ty, .. } => {
                    self.add_type_of(n.id, *ty);
                }
                CanonNodeKind::Impl { for_ty, for_trait, .. } => {
                    self.add_type_of(n.id, *for_ty);
                    if let Some(t) = for_trait {
                        self.edges.push((n.id.0, t.0, EdgeKind::ImplTrait));
                    }
                }
                _ => {}
            }
        }
    }

    pub fn edges(&self) -> &[(u32, u32, EdgeKind)] {
        &self.edges
    }

    pub fn build(self) -> CsrGraph<CanonId, EdgeKind> {
        let node_ids: Vec<CanonId> = (0..self.v as u32).map(CanonId).collect();
        CsrGraph::from_edges(node_ids, self.edges)
    }
}

use canon::csr_graph::CsrGraph;
use canon::edge::EdgeKind;
use canon::node::{CanonId, CanonNodeKind};
use canon::CanonIR;
use std::collections::HashMap;

pub struct ValueGraphBuilder {
    v: usize,
    edges: Vec<(u32, u32, EdgeKind)>,
}

impl ValueGraphBuilder {
    pub fn new(v: usize) -> Self {
        Self { v, edges: Vec::new() }
    }

    pub fn add_const_dep(&mut self, src: CanonId, dst: CanonId) {
        self.edges.push((src.0, dst.0, EdgeKind::ConstDep));
    }

    pub fn derive_from_ir(&mut self, ir: &CanonIR) {
        let consts: HashMap<String, CanonId> = ir
            .nodes
            .iter()
            .filter_map(|n| match &n.kind {
                CanonNodeKind::Const { name_id, .. } | CanonNodeKind::Static { name_id, .. } => Some((ir.lookup_name(*name_id).to_string(), n.id)),
                _ => None,
            })
            .collect();

        for n in &ir.nodes {
            let value = match &n.kind {
                CanonNodeKind::Const { value_id, .. } | CanonNodeKind::Static { value_id, .. } => ir.lookup_name(*value_id),
                _ => continue,
            };
            for (name, dep_id) in &consts {
                if *dep_id == n.id {
                    continue;
                }
                if contains_ident(value, name) {
                    self.add_const_dep(n.id, *dep_id);
                }
            }
        }
    }

    pub fn edges(&self) -> &[(u32, u32, EdgeKind)] {
        &self.edges
    }

    pub fn build(self) -> CsrGraph<CanonId, EdgeKind> {
        let node_ids: Vec<CanonId> = (0..self.v as u32).map(CanonId).collect();
        CsrGraph::from_edges(node_ids, self.edges)
    }
}

fn contains_ident(text: &str, ident: &str) -> bool {
    text.split(|c: char| !(c.is_ascii_alphanumeric() || c == '_')).any(|tok| tok == ident)
}

