pub(crate) fn csr_to_adj<ND, ED>(graph: &canon::csr_graph::CsrGraph<ND, ED>) -> Vec<Vec<usize>> {
    let v = graph.vertex_count();
    (0..v).map(|i| graph.neighbours(NodeId(i as u32)).map(|(dst, _)| dst.index()).collect()).collect()
}

pub(crate) fn graph_to_csr<ND, ED>(graph: &canon::csr_graph::CsrGraph<ND, ED>) -> Csr {
    let row_ptr: Vec<i32> = graph.row_ptr.iter().map(|&x| x as i32).collect();
    let col_idx: Vec<i32> = graph.col_idx.iter().map(|&x| x as i32).collect();
    Csr { row_ptr, col_idx }
}

pub(crate) fn global_csr_to_adj(ir: &CanonIR) -> Vec<Vec<usize>> {
    graph_csr_to_adj(&ir.graph_csr)
}

pub(crate) fn global_csr_rev_to_adj(ir: &CanonIR) -> Vec<Vec<usize>> {
    graph_csr_to_adj(&ir.graph_csr_rev)
}

fn graph_csr_to_adj(csr: &canon::ir::CanonCsr) -> Vec<Vec<usize>> {
    let row_ptr: Vec<i32> = csr.row_ptr.iter().map(|&x| x as i32).collect();
    let col_idx: Vec<i32> = csr.col_idx.iter().map(|&x| x as i32).collect();
    let graph = Csr { row_ptr, col_idx };
    (0..graph.vertex_count()).map(|i| graph.neighbours(i).iter().map(|&dst| dst as usize).collect()).collect()
}

#[cfg(feature = "cuda")]
use crate::solver::gpu_algorithms::reachability_gpu;
#[cfg(feature = "cuda")]
use crate::solver::graph_to_csr;
use algorithms::graph::region::outlives_cycles;
use anyhow::{bail, Result};
use canon::id::NodeId;
use canon::node::CanonNodeKind;
use canon::CanonIR;

pub fn solve(ir: &CanonIR) -> Result<()> {
    let v = ir.region_graph.vertex_count();
    if v == 0 {
        return Ok(());
    }

    #[cfg(feature = "cuda")]
    {
        return solve_with_gpu(ir, v);
    }
    #[cfg(not(feature = "cuda"))]
    {
        return solve_cpu(ir, v);
    }
}

#[cfg(not(feature = "cuda"))]
fn solve_cpu(ir: &CanonIR, v: usize) -> Result<()> {
    let mut adj: Vec<Vec<usize>> = vec![Vec::new(); v];
    for (idx, node) in ir.nodes.iter().enumerate() {
        if idx >= v {
            break;
        }
        if !matches!(&node.kind, CanonNodeKind::Lifetime { .. }) {
            continue;
        }
        for (nb, _edge) in ir.region_graph.neighbours(NodeId(node.id.0)) {
            adj[idx].push(nb.index());
        }
    }

    let cycles = outlives_cycles(&adj);
    if cycles.is_empty() {
        log::info!("borrow_solver: region graph is acyclic - {} lifetime node(s) valid", v);
        return Ok(());
    }

    let names: Vec<String> = cycles
        .iter()
        .map(|scc| {
            scc.iter()
                .filter_map(|&i| ir.nodes.get(i).and_then(|n| if let CanonNodeKind::Lifetime { name_id } = &n.kind { Some(ir.lookup_name(*name_id).to_string()) } else { None }))
                .collect::<Vec<_>>()
                .join(", ")
        })
        .collect();

    bail!("borrow_solver: conflicting lifetime constraints - cycles: [{}]", names.join("; "));
}

#[cfg(feature = "cuda")]
fn solve_with_gpu(ir: &CanonIR, v: usize) -> Result<()> {
    let mut is_lifetime = vec![false; v];
    for idx in 0..v {
        if matches!(ir.nodes.get(idx).map(|n| &n.kind), Some(CanonNodeKind::Lifetime { .. })) {
            is_lifetime[idx] = true;
        }
    }

    let mut indegree = vec![0usize; v];
    for src in 0..v {
        if !is_lifetime[src] {
            continue;
        }
        for (dst, _edge) in ir.region_graph.neighbours(NodeId(src as u32)) {
            let dst_idx = dst.index();
            if dst_idx < v && is_lifetime[dst_idx] {
                indegree[dst_idx] += 1;
            }
        }
    }

    let mut roots: Vec<usize> = (0..v).filter(|&i| is_lifetime[i] && indegree[i] == 0).collect();
    if roots.is_empty() {
        roots = (0..v).filter(|&i| is_lifetime[i]).collect();
    }
    if roots.is_empty() {
        return Ok(());
    }

    let csr = graph_to_csr(&ir.region_graph);
    let reachable = reachability_gpu(&csr, &roots);

    let mut adj: Vec<Vec<usize>> = vec![Vec::new(); v];
    for idx in 0..v {
        if !is_lifetime[idx] {
            continue;
        }
        if !reachable.get(idx).copied().unwrap_or(false) {
            continue;
        }
        for (nb, _edge) in ir.region_graph.neighbours(NodeId(idx as u32)) {
            let nb_idx = nb.index();
            if nb_idx < v && is_lifetime[nb_idx] && reachable.get(nb_idx).copied().unwrap_or(false) {
                adj[idx].push(nb_idx);
            }
        }
    }

    let cycles = outlives_cycles(&adj);
    if cycles.is_empty() {
        log::info!("borrow_solver: region graph is acyclic - {} lifetime node(s) valid", v);
        return Ok(());
    }

    let names: Vec<String> = cycles
        .iter()
        .map(|scc| {
            scc.iter()
                .filter_map(|&i| ir.nodes.get(i).and_then(|n| if let CanonNodeKind::Lifetime { name_id } = &n.kind { Some(ir.lookup_name(*name_id).to_string()) } else { None }))
                .collect::<Vec<_>>()
                .join(", ")
        })
        .collect();

    bail!("borrow_solver: conflicting lifetime constraints - cycles: [{}]", names.join("; "));
}

use crate::solver::csr_to_adj;
use algorithms::graph::dfs::dfs;
use anyhow::Result;
use canon::CanonIR;

pub fn solve(ir: &mut CanonIR) -> Result<()> {
    let v = ir.call_graph.vertex_count();
    if v == 0 {
        return Ok(());
    }

    let adj = csr_to_adj(&ir.call_graph);
    let mut in_degree = vec![0usize; v];
    for neighbours in &adj {
        for &dst in neighbours {
            in_degree[dst] += 1;
        }
    }

    let mut reachable = vec![false; v];
    for root in 0..v {
        if in_degree[root] == 0 {
            for idx in dfs(&adj, root) {
                reachable[idx] = true;
            }
        }
    }

    let _dead: Vec<usize> = (0..v).filter(|&i| !reachable[i]).collect();
    Ok(())
}

use crate::solver::csr_to_adj;
#[cfg(not(feature = "cuda"))]
use crate::solver::gpu_algorithms::dfs;
use crate::solver::gpu_algorithms::dominators;
#[cfg(feature = "cuda")]
use crate::solver::gpu_algorithms::reachability_gpu;
#[cfg(feature = "cuda")]
use crate::solver::graph_to_csr;
use anyhow::Result;
use canon::CanonIR;
use std::collections::HashMap;

pub fn solve(ir: &mut CanonIR) -> Result<()> {
    let v = ir.cfg_graph.vertex_count();
    if v == 0 {
        return Ok(());
    }

    let adj = csr_to_adj(&ir.cfg_graph);
    let reachable: Vec<bool> = {
        #[cfg(feature = "cuda")]
        {
            let csr = graph_to_csr(&ir.cfg_graph);
            reachability_gpu(&csr, &[0])
        }
        #[cfg(not(feature = "cuda"))]
        {
            let reached = dfs(&adj, 0);
            let mut mask = vec![false; v];
            for idx in reached {
                if idx < v {
                    mask[idx] = true;
                }
            }
            mask
        }
    };
    let _dead: Vec<usize> = reachable.iter().enumerate().filter_map(|(i, &r)| if r { None } else { Some(i) }).collect();

    let mut preds: HashMap<usize, Vec<usize>> = HashMap::new();
    for (u, nbrs) in adj.iter().enumerate() {
        for &w in nbrs {
            preds.entry(w).or_default().push(u);
        }
    }
    let _dom = dominators(v, &preds, 0);

    Ok(())
}

use algorithms::constraints::sat::{self, Cnf, Lit};
use algorithms::graph::scc::kosaraju_scc;
use algorithms::graph::topological_sort::topological_sort;
use anyhow::Result;
use canon::edge::EdgeKind;
use canon::id::NodeId;
use canon::node::CanonNodeKind;
use canon::CanonIR;

#[derive(Debug, Clone)]
pub struct RenameTransform {
    pub var_id: usize,
    pub src_idx: usize,
    pub dst_idx: usize,
    pub old_name: String,
    pub new_name: String,
}

#[derive(Debug, Clone)]
pub struct RenameConstraintProblem {
    pub transforms: Vec<RenameTransform>,
    pub dependencies: Vec<(usize, usize)>,
    pub conflicts: Vec<(usize, usize)>,
    pub cnf: Cnf,
    pub topo_order: Vec<usize>,
    pub sccs: Vec<Vec<usize>>,
}

pub fn solve(ir: &mut CanonIR) -> Result<()> {
    let problem = build_problem(ir);
    let Some(model) = sat::solve(&problem.cnf) else {
        emit_diag(
            ir,
            &format!(
                "constraint_solver:unsat vars={} deps={} conflicts={}",
                problem.transforms.len(),
                problem.dependencies.len(),
                problem.conflicts.len()
            ),
        );
        return Ok(());
    };

    let selected = model.iter().filter(|&&v| v).count();
    emit_diag(
        ir,
        &format!(
            "constraint_solver:sat selected={}/{} deps={} conflicts={}",
            selected,
            problem.transforms.len(),
            problem.dependencies.len(),
            problem.conflicts.len()
        ),
    );
    Ok(())
}

pub fn build_problem(ir: &CanonIR) -> RenameConstraintProblem {
    let transforms = collect_rename_transforms(ir);
    let dependencies = build_dependencies(&transforms);
    let conflicts = build_conflicts(&transforms);
    let cnf = build_cnf(transforms.len(), &dependencies, &conflicts);

    let mut dep_adj = vec![Vec::new(); transforms.len()];
    for &(a, b) in &dependencies {
        dep_adj[a].push(b);
    }
    let topo_order = topological_sort(&dep_adj);
    let sccs = kosaraju_scc(&dep_adj);

    RenameConstraintProblem {
        transforms,
        dependencies,
        conflicts,
        cnf,
        topo_order,
        sccs,
    }
}

pub fn is_subset_valid(problem: &RenameConstraintProblem, subset: &[usize]) -> bool {
    let mut selected = vec![false; problem.transforms.len()];
    for &idx in subset {
        if idx >= selected.len() {
            return false;
        }
        selected[idx] = true;
    }
    is_selected_vector_valid(problem, &selected)
}

pub fn is_selected_vector_valid(problem: &RenameConstraintProblem, selected: &[bool]) -> bool {
    if selected.len() != problem.transforms.len() {
        return false;
    }
    for &(a, b) in &problem.dependencies {
        if selected[b] && !selected[a] {
            return false;
        }
    }
    for &(a, b) in &problem.conflicts {
        if selected[a] && selected[b] {
            return false;
        }
    }
    true
}

fn collect_rename_transforms(ir: &CanonIR) -> Vec<RenameTransform> {
    let mut out = Vec::new();
    for src_idx in 0..ir.name_graph.vertex_count() {
        let src_name = node_name(ir, src_idx);
        let Some(new_name) = src_name else {
            continue;
        };
        for (dst_id, edge) in ir.name_graph.neighbours(NodeId(src_idx as u32)) {
            if *edge != EdgeKind::Renames {
                continue;
            }
            let dst_idx = dst_id.index();
            let Some(old_name) = node_name(ir, dst_idx) else {
                continue;
            };
            let var_id = out.len();
            out.push(RenameTransform {
                var_id,
                src_idx,
                dst_idx,
                old_name,
                new_name: new_name.clone(),
            });
        }
    }
    out
}

fn build_dependencies(transforms: &[RenameTransform]) -> Vec<(usize, usize)> {
    // dep(a,b): if a renames a symbol that is used as source in b, enforce a before b.
    let mut deps = Vec::new();
    for a in transforms {
        for b in transforms {
            if a.var_id == b.var_id {
                continue;
            }
            if a.dst_idx == b.src_idx {
                deps.push((a.var_id, b.var_id));
            }
        }
    }
    deps.sort_unstable();
    deps.dedup();
    deps
}

fn build_conflicts(transforms: &[RenameTransform]) -> Vec<(usize, usize)> {
    let mut conflicts = Vec::new();
    for i in 0..transforms.len() {
        for j in (i + 1)..transforms.len() {
            let a = &transforms[i];
            let b = &transforms[j];
            let same_target = a.dst_idx == b.dst_idx;
            let same_new_name = a.new_name == b.new_name && a.dst_idx != b.dst_idx;
            if same_target || same_new_name {
                conflicts.push((i, j));
            }
        }
    }
    conflicts
}

fn build_cnf(num_vars: usize, dependencies: &[(usize, usize)], conflicts: &[(usize, usize)]) -> Cnf {
    let mut cnf = Cnf::new(num_vars);
    // dep(a,b) => b -> a
    for &(a, b) in dependencies {
        cnf.add_clause(vec![Lit::neg(b), Lit::pos(a)]);
    }
    // conflict(a,b) => !(a && b)
    for &(a, b) in conflicts {
        cnf.add_clause(vec![Lit::neg(a), Lit::neg(b)]);
    }
    cnf
}

fn node_name(ir: &CanonIR, idx: usize) -> Option<String> {
    let kind = &ir.nodes.get(idx)?.kind;
    match kind {
        CanonNodeKind::Struct { name_id, .. }
        | CanonNodeKind::Enum { name_id, .. }
        | CanonNodeKind::Trait { name_id, .. }
        | CanonNodeKind::Fn { name_id, .. }
        | CanonNodeKind::TypeRef { name_id }
        | CanonNodeKind::TypeAlias { name_id, .. }
        | CanonNodeKind::Const { name_id, .. }
        | CanonNodeKind::Static { name_id, .. }
        | CanonNodeKind::ExternCrate { name_id, .. }
        | CanonNodeKind::Lifetime { name_id }
        | CanonNodeKind::GenericParam { name_id, .. }
        | CanonNodeKind::Param { name_id, .. }
        | CanonNodeKind::Variant { name_id, .. } => Some(ir.lookup_name(*name_id).to_string()),
        CanonNodeKind::Use { alias, path_id, .. } => {
            if let Some(a) = alias {
                Some(ir.lookup_name(*a).to_string())
            } else {
                Some(ir.lookup_path(*path_id).to_string())
            }
        }
        _ => None,
    }
}

fn emit_diag(ir: &mut CanonIR, label: &str) {
    let name_id = ir.intern_name(label);
    let id = ir.push_node(CanonNodeKind::TypeRef { name_id });
    ir.emit_order.push(id);
}

use crate::solver::csr_to_adj;
use algorithms::graph::topological_sort::topological_sort;
use anyhow::{bail, Result};
use canon::node::CanonNodeKind;
use canon::CanonIR;

pub fn solve(ir: &CanonIR) -> Result<()> {
    let const_nodes: Vec<usize> = ir.nodes.iter().filter(|n| matches!(&n.kind, CanonNodeKind::Const { .. } | CanonNodeKind::Static { .. })).map(|n| n.id.0 as usize).collect();

    if const_nodes.is_empty() {
        return Ok(());
    }

    let v = ir.value_graph.vertex_count();
    if v == 0 {
        return Ok(());
    }
    let adj = csr_to_adj(&ir.value_graph);
    let order = topological_sort(&adj);
    if order.len() != v {
        bail!("const_solver: circular ConstDep dependency detected (cycle in G_value)");
    }

    log::info!("const_solver: {} const/static node(s) validated, eval order is acyclic", const_nodes.len());
    Ok(())
}

use crate::solver::csr_to_adj;
use algorithms::graph::scc::kosaraju_scc;
use anyhow::Result;
use canon::node::CanonNodeKind;
use canon::CanonIR;

fn node_label(ir: &CanonIR, kind: &CanonNodeKind) -> String {
    match kind {
        CanonNodeKind::Struct { name_id, .. } => format!("struct {}", ir.lookup_name(*name_id)),
        CanonNodeKind::Trait { name_id, .. } => format!("trait {}", ir.lookup_name(*name_id)),
        CanonNodeKind::Fn { name_id, .. } => format!("fn {}", ir.lookup_name(*name_id)),
        CanonNodeKind::TypeAlias { name_id, .. } => format!("type {}", ir.lookup_name(*name_id)),
        CanonNodeKind::TypeRef { name_id } => format!("ref {}", ir.lookup_name(*name_id)),
        _ => "?".to_string(),
    }
}

pub fn solve(ir: &mut CanonIR) -> Result<()> {
    let v = ir.type_graph.vertex_count();
    if v == 0 {
        return Ok(());
    }

    let adj = csr_to_adj(&ir.type_graph);
    let sccs = kosaraju_scc(&adj);

    for scc in sccs.iter().filter(|s| s.len() > 1) {
        let labels: Vec<String> = scc.iter().filter_map(|&idx| ir.nodes.get(idx).map(|n| node_label(ir, &n.kind))).collect();
        let diag_label = format!("cycle:{}", labels.join(" -> "));
        log::debug!("DIAG cycle_diag_solver: type cycle detected [{}]: {}", scc.len(), &diag_label[6..]);
        let name_id = ir.intern_name(&diag_label);
        let diag_id = ir.push_node(CanonNodeKind::TypeRef { name_id });
        ir.emit_order.push(diag_id);
    }

    Ok(())
}

use anyhow::Result;
use canon::ir::CanonIR;
use canon::node::{CanonNodeKind, NameId};
use std::collections::HashMap;

/// Stdlib / language pseudo-crate roots that must not appear as Cargo dependencies.
const BUILTIN_ROOTS: &[&str] = &["std", "core", "alloc", "proc_macro", "crate", "self", "super"];

/// Populate `Crate.dependencies` from the Use nodes present in the IR.
///
/// For every `CanonNodeKind::Use { path_id, .. }` the solver:
/// 1. Extracts the leading path segment (e.g. `"serde"` from `"serde::Deserialize"`).
/// 2. Skips builtin roots and single-segment paths that equal the crate name.
/// 3. Interns the crate root as a `PathId` and appends it to `Crate.dependencies`
///    (deduplicating by value).
///
/// This is the canonical replacement for `infer_dependencies` / `roots_from_text`
/// which were deleted from `layout/mod.rs` as part of g1.
pub fn solve(ir: &mut CanonIR) -> Result<()> {
    // Collect the crate name so we can skip self-references.
    let mut crate_name = String::new();
    let mut declared_packages: HashMap<String, Option<String>> = HashMap::new();
    for n in &ir.nodes {
        if let CanonNodeKind::Crate { name_id, declared_dependencies, .. } = &n.kind {
            crate_name = ir.lookup_name(*name_id).to_string();
            for dep in declared_dependencies {
                let root = ir.lookup_path(dep.crate_root).to_string();
                let pkg = dep.package_name.map(|nid| ir.lookup_name(nid).to_string());
                declared_packages.insert(root, pkg);
            }
            break;
        }
    }
    // Gather all external crate roots referenced by Use nodes.
    let mut extern_roots: Vec<String> = Vec::new();
    let mut push_root = |root: &str| {
        if root.is_empty() {
            return;
        }
        if BUILTIN_ROOTS.contains(&root) {
            return;
        }
        if root == crate_name.as_str() {
            return;
        }
        if !extern_roots.iter().any(|r| r == root) {
            extern_roots.push(root.to_string());
        }
    };

    for node in &ir.nodes {
        if let CanonNodeKind::Use { path_id, .. } = &node.kind {
            let path = ir.lookup_path(*path_id);
            let root = path.split("::").next().unwrap_or("").trim();
            push_root(root);
        }
        if let CanonNodeKind::PathRef { path_id } = &node.kind {
            let path = ir.lookup_path(*path_id);
            let root = path.split("::").next().unwrap_or("").trim();
            push_root(root);
        }
    }

    if extern_roots.is_empty() {
        return Ok(());
    }

    // Intern each root and write into the Crate node fields.
    let mut path_ids = Vec::new();
    let mut package_ids: Vec<Option<NameId>> = Vec::new();
    for root in &extern_roots {
        path_ids.push(ir.intern_path(root));
        let pkg_id = declared_packages.get(root).and_then(|p| p.as_deref()).map(|pkg| NameId(ir.name_intern.intern(pkg)));
        package_ids.push(pkg_id);
    }

    for node in ir.nodes.iter_mut() {
        if let CanonNodeKind::Crate { dependencies, dependency_packages, .. } = &mut node.kind {
            *dependencies = path_ids.clone();
            *dependency_packages = package_ids.clone();
            break;
        }
    }

    Ok(())
}

use algorithms::control_flow::dominators::post_dominators;
use anyhow::{bail, Result};
use canon::node::{CanonId, CanonNodeKind, CfgOp};
use canon::CanonIR;

pub fn solve(ir: &CanonIR) -> Result<()> {
    for node in &ir.nodes {
        let (fname, body_id) = match &node.kind {
            CanonNodeKind::Fn { name_id, body: Some(body), .. } => (ir.lookup_name(*name_id).to_string(), *body),
            _ => continue,
        };

        let blocks = match &ir.node(body_id).kind {
            CanonNodeKind::Body { blocks } if !blocks.is_empty() => blocks,
            _ => continue,
        };

        let n = blocks.len();
        let mut succs: Vec<Vec<usize>> = vec![Vec::new(); n];
        let mut exit_nodes: Vec<usize> = Vec::new();

        for (i, bb_id) in blocks.iter().enumerate() {
            let CanonNodeKind::BasicBlock { ops, next } = &ir.node(*bb_id).kind else {
                continue;
            };

            if let Some(last) = ops.last() {
                match last {
                    CfgOp::Goto(t) => {
                        let t = *t as usize;
                        if t < n {
                            succs[i].push(t);
                        }
                    }
                    CfgOp::Branch { true_bb, false_bb, .. } => {
                        let t = *true_bb as usize;
                        let f = *false_bb as usize;
                        if t < n {
                            succs[i].push(t);
                        }
                        if f < n {
                            succs[i].push(f);
                        }
                    }
                    CfgOp::Return(_) => exit_nodes.push(i),
                    CfgOp::Unreachable => {}
                    _ => {
                        if let Some(nx) = next {
                            let nx = *nx as usize;
                            if nx < n {
                                succs[i].push(nx);
                            }
                        }
                    }
                }
            }
        }

        if exit_nodes.is_empty() {
            exit_nodes.push(n - 1);
        }

        let post_dom = post_dominators(n, &succs, &exit_nodes);

        for i in 0..n {
            let has_decls = block_decl_names(ir, blocks[i]).next().is_some();
            if has_decls && !post_dom[i].contains(&i) {
                bail!("drop_solver: `{}` block {} has let-bindings but does not post-dominate itself - malformed CFG", fname, i);
            }
        }

        let decl_order: Vec<String> = blocks.iter().flat_map(|bb_id| block_decl_names(ir, *bb_id)).collect();

        if decl_order.is_empty() {
            continue;
        }

        let mut expected_drop = decl_order.clone();
        expected_drop.reverse();

        if exit_nodes.len() > 1 {
            for &exit in &exit_nodes {
                let exit_decls: Vec<String> = blocks.iter().enumerate().filter(|(i, _)| post_dom[exit].contains(i)).flat_map(|(_, bb)| block_decl_names(ir, *bb)).collect();

                let mut exit_drop = exit_decls.clone();
                exit_drop.reverse();

                if !decl_order.is_empty() && !exit_decls.is_empty() && !is_subsequence(&exit_drop, &expected_drop) {
                    bail!("drop_solver: `{}` exit block {} has inconsistent drop order on this path. expected suffix: {:?}, got: {:?}", fname, exit, expected_drop, exit_drop);
                }
            }
        }

        log::info!("drop_solver: `{}` - {} binding(s), drop order: {:?}", fname, decl_order.len(), expected_drop);
    }

    Ok(())
}

fn block_decl_names<'a>(ir: &'a CanonIR, bb_id: CanonId) -> impl Iterator<Item = String> + 'a {
    let mut out = Vec::new();
    if let CanonNodeKind::BasicBlock { ops, .. } = &ir.node(bb_id).kind {
        for op in ops {
            if let CfgOp::Let { lhs, .. } = op {
                if let CanonNodeKind::Local { name_id, .. } = &ir.node(*lhs).kind {
                    out.push(ir.lookup_name(*name_id).to_string());
                }
            }
        }
    }
    out.into_iter()
}

fn is_subsequence(needle: &[String], haystack: &[String]) -> bool {
    let mut ni = 0;
    for h in haystack {
        if ni == needle.len() {
            break;
        }
        if needle[ni] == *h {
            ni += 1;
        }
    }
    ni == needle.len()
}

use crate::solver::constraint_solver::{build_problem, is_subset_valid};
use crate::solver::search_optimizer_solver::optimize;
use algorithms::optimization::delta_debug::ddmin;
use anyhow::Result;
use canon::node::CanonNodeKind;
use canon::CanonIR;
use std::collections::HashSet;

const MAX_ATTRIBUTIONS: usize = 8;

pub fn solve(ir: &mut CanonIR) -> Result<()> {
    let problem = build_problem(ir);
    if problem.transforms.is_empty() {
        return Ok(());
    }

    let selected = optimize(&problem, 32);
    let selected_set: HashSet<usize> = selected.iter().copied().collect();
    let rejected: Vec<usize> = (0..problem.transforms.len())
        .filter(|i| !selected_set.contains(i))
        .collect();

    let mut emitted = 0usize;
    for rid in rejected.into_iter().take(MAX_ATTRIBUTIONS) {
        let transform = &problem.transforms[rid];
        let self_invalid = !is_subset_valid(&problem, &[rid]);
        let blockers = if self_invalid {
            Vec::new()
        } else {
            ddmin(&selected, |subset| {
                let mut trial = subset.to_vec();
                trial.push(rid);
                !is_subset_valid(&problem, &trial)
            })
        };

        let reason = if self_invalid {
            "self_invalid"
        } else if blockers.is_empty() {
            "heuristic_rejected"
        } else {
            "blocked_by_constraints"
        };

        let mut details = format!(
            "error_attribution:{} {}->{}",
            reason, transform.old_name, transform.new_name
        );
        if !blockers.is_empty() {
            let labels: Vec<String> = blockers
                .iter()
                .filter_map(|&bid| problem.transforms.get(bid))
                .map(|t| format!("{}->{}", t.old_name, t.new_name))
                .collect();
            details.push_str(&format!(" blockers=[{}]", labels.join(", ")));
        }
        emit_diag(ir, &details);
        emitted += 1;
    }

    emit_diag(ir, &format!("error_attribution_solver:emitted={}", emitted));
    Ok(())
}

fn emit_diag(ir: &mut CanonIR, label: &str) {
    let name_id = ir.intern_name(label);
    let id = ir.push_node(CanonNodeKind::TypeRef { name_id });
    ir.emit_order.push(id);
}

use anyhow::Result;
use canon::node::{CanonNodeKind, CfgOp};
use canon::CanonIR;

pub fn solve(ir: &CanonIR) -> Result<()> {
    let enums: Vec<(String, Vec<String>)> = ir
        .nodes
        .iter()
        .filter_map(|n| {
            if let CanonNodeKind::Enum { name_id, variants, .. } = &n.kind {
                let vnames: Vec<String> =
                    variants.iter().filter_map(|id| if let CanonNodeKind::Variant { name_id, .. } = &ir.node(*id).kind { Some(ir.lookup_name(*name_id).to_string()) } else { None }).collect();
                Some((ir.lookup_name(*name_id).to_string(), vnames))
            } else {
                None
            }
        })
        .collect();

    if enums.is_empty() {
        return Ok(());
    }

    let mut body_text = String::new();
    for node in &ir.nodes {
        if let CanonNodeKind::Fn { body: Some(body_id), .. } = &node.kind {
            collect_body_text(ir, *body_id, &mut body_text);
        }
    }

    for (enum_name, variants) in &enums {
        if variants.is_empty() {
            continue;
        }
        if body_text.contains("_ =>") || body_text.contains("match _") {
            log::info!("exhaustiveness_solver: enum `{}` - wildcard arm present, assumed covered", enum_name);
            continue;
        }
        let uncovered: Vec<&str> = variants.iter().filter(|v| !body_text.contains(v.as_str())).map(|v| v.as_str()).collect();
        if !uncovered.is_empty() {
            log::warn!("exhaustiveness_solver: enum `{}` may have uncovered variants: {:?}", enum_name, uncovered);
        } else {
            log::info!("exhaustiveness_solver: enum `{}` - all {} variant(s) referenced", enum_name, variants.len());
        }
    }

    Ok(())
}

fn collect_body_text(ir: &CanonIR, body_id: canon::node::CanonId, out: &mut String) {
    let CanonNodeKind::Body { blocks } = &ir.node(body_id).kind else {
        return;
    };

    for bb_id in blocks {
        let CanonNodeKind::BasicBlock { ops, .. } = &ir.node(*bb_id).kind else {
            continue;
        };
        for op in ops {
            match op {
                CfgOp::Expr(local_id) => {
                    if let CanonNodeKind::Local { name_id, .. } = &ir.node(*local_id).kind {
                        out.push_str(ir.lookup_name(*name_id));
                        out.push('\n');
                    }
                }
                _ => {}
            }
        }
    }
}

use crate::solver::csr_to_adj;
use algorithms::graph::scc::kosaraju_scc;
use anyhow::Result;
use canon::node::{CanonId, CanonNodeKind, TypeKind};
use canon::CanonIR;

fn node_ty(ir: &CanonIR, idx: usize) -> Option<CanonId> {
    match &ir.nodes.get(idx)?.kind {
        CanonNodeKind::Fn { sig_id, .. } => match &ir.node(*sig_id).kind {
            CanonNodeKind::FnSig { ret, .. } => Some(*ret),
            _ => None,
        },
        CanonNodeKind::TypeAlias { ty, .. } => Some(*ty),
        CanonNodeKind::TypeRef { .. } => Some(canon::node::CanonId(idx as u32)),
        _ => None,
    }
}

fn is_concrete(ir: &CanonIR, ty: CanonId) -> bool {
    match &ir.node(ty).kind {
        CanonNodeKind::Type { kind: TypeKind::Param(_) } => false,
        CanonNodeKind::TypeRef { name_id } => {
            let s = ir.lookup_name(*name_id);
            !(s.len() == 1 && s.chars().next().is_some_and(|c| c.is_uppercase()))
        }
        _ => true,
    }
}

pub fn solve(ir: &CanonIR) -> Result<()> {
    let v = ir.type_graph.vertex_count();
    if v == 0 {
        return Ok(());
    }

    let adj = csr_to_adj(&ir.type_graph);
    let sccs = kosaraju_scc(&adj);

    for scc in sccs.iter().filter(|s| s.len() > 1) {
        let tys: Vec<(usize, CanonId)> = scc.iter().filter_map(|&idx| node_ty(ir, idx).map(|t| (idx, t))).collect();

        let concrete: Vec<(usize, CanonId)> = tys.iter().copied().filter(|(_, t)| is_concrete(ir, *t)).collect();

        if concrete.len() > 1 {
            let first_ty = concrete[0].1;
            for &(idx, ty) in &concrete[1..] {
                if ty != first_ty {
                    eprintln!("WARN generic_solver: type conflict in SCC: node {} has {:?} vs {:?}", idx, ty, first_ty);
                }
            }
        }
    }

    Ok(())
}

use crate::solver::constraint_solver::build_problem;
use anyhow::Result;
use canon::node::CanonNodeKind;
use canon::CanonIR;

pub fn solve(ir: &mut CanonIR) -> Result<()> {
    let problem = build_problem(ir);
    if problem.transforms.is_empty() {
        return Ok(());
    }

    let cyclic: Vec<&Vec<usize>> = problem.sccs.iter().filter(|c| c.len() > 1).collect();
    if !cyclic.is_empty() {
        for component in cyclic {
            let names: Vec<String> = component
                .iter()
                .filter_map(|&vid| problem.transforms.get(vid))
                .map(|t| format!("{}->{}", t.old_name, t.new_name))
                .collect();
            emit_diag(
                ir,
                &format!("graph_dependency_solver:cycle {}", names.join(" | ")),
            );
        }
    } else {
        emit_diag(
            ir,
            &format!(
                "graph_dependency_solver:ok vars={} order={}",
                problem.transforms.len(),
                problem.topo_order.len()
            ),
        );
    }

    Ok(())
}

fn emit_diag(ir: &mut CanonIR, label: &str) {
    let name_id = ir.intern_name(label);
    let id = ir.push_node(CanonNodeKind::TypeRef { name_id });
    ir.emit_order.push(id);
}

#[cfg(feature = "cuda")]
pub use algorithms::constraints::ac3::ac3_gpu_apply;
pub use algorithms::control_flow::dominators::dominators;
pub use algorithms::graph::dfs::dfs;
#[cfg(feature = "cuda")]
pub use algorithms::graph::reachability::reachability_gpu;
pub use algorithms::graph::scc::kosaraju_scc;

use anyhow::Result;
use canon::edge::EdgeKind;
use canon::id::NodeId;
use canon::node::CanonNodeKind;
use canon::CanonIR;
use std::collections::{HashMap, HashSet};

pub fn solve(ir: &CanonIR) -> Result<()> {
    let target_ids: HashSet<u32> = ir
        .nodes
        .iter()
        .filter_map(|n| match &n.kind {
            CanonNodeKind::Struct { .. } | CanonNodeKind::Enum { .. } | CanonNodeKind::Trait { .. } | CanonNodeKind::TypeAlias { .. } => Some(n.id.0),
            _ => None,
        })
        .collect();

    let mut impl_keys: HashMap<(u32, Option<u32>), Vec<usize>> = HashMap::new();

    for (idx, node) in ir.nodes.iter().enumerate() {
        if let CanonNodeKind::Impl { for_ty, for_trait, .. } = &node.kind {
            if !target_ids.contains(&for_ty.0) {
                eprintln!("WARN impl_solver: Impl[{}] targets unknown type {:?}", idx, for_ty);
            }
            impl_keys.entry((for_ty.0, for_trait.map(|t| t.0))).or_default().push(idx);
        }
    }

    for ((for_ty, for_trait), indices) in &impl_keys {
        if indices.len() > 1 {
            eprintln!("WARN impl_solver: duplicate impl of {:?} for target {:?} at nodes {:?}", for_trait, for_ty, indices);
        }
    }

    let type_v = ir.type_graph.vertex_count();
    for (idx, node) in ir.nodes.iter().enumerate() {
        let CanonNodeKind::Impl { for_trait, .. } = &node.kind else {
            continue;
        };
        let mut implref_targets: Vec<u32> = Vec::new();
        if idx < type_v {
            for (dst_id, edge) in ir.type_graph.neighbours(NodeId(idx as u32)) {
                if *edge == EdgeKind::ImplRef {
                    implref_targets.push(dst_id.0);
                }
            }
        }
        implref_targets.sort_unstable();
        implref_targets.dedup();

        match (for_trait, implref_targets.as_slice()) {
            (Some(expected), [actual]) if expected.0 != *actual => {
                eprintln!("WARN impl_solver: Impl[{}] for_trait field {:?} mismatches type_graph ImplRef {:?}", idx, expected, actual);
            }
            (Some(_), []) => {
                eprintln!("WARN impl_solver: Impl[{}] missing ImplRef edge in type_graph", idx);
            }
            (None, [actual, ..]) => {
                eprintln!("WARN impl_solver: inherent Impl[{}] has unexpected ImplRef edge(s) {:?}", idx, implref_targets);
                let _ = actual;
            }
            (_, [_, _, ..]) => {
                eprintln!("WARN impl_solver: Impl[{}] has multiple ImplRef edges {:?}", idx, implref_targets);
            }
            _ => {}
        }
    }

    Ok(())
}

use crate::solver::{csr_to_adj, global_csr_rev_to_adj, global_csr_to_adj};
use algorithms::graph::topological_sort::topological_sort;
use anyhow::{bail, Result};
use canon::edge::EdgeKind;
use canon::id::NodeId;
use canon::node::CanonNodeKind;
use canon::CanonIR;

pub fn solve(ir: &CanonIR) -> Result<()> {
    let v = ir.nodes.len();

    let graphs: &[(&str, &dyn Fn() -> Vec<Vec<usize>>)] = &[
        ("name", &|| csr_to_adj(&ir.name_graph)),
        ("type", &|| csr_to_adj(&ir.type_graph)),
        ("call", &|| csr_to_adj(&ir.call_graph)),
        ("module", &|| csr_to_adj(&ir.module_graph)),
        ("cfg", &|| csr_to_adj(&ir.cfg_graph)),
        ("region", &|| csr_to_adj(&ir.region_graph)),
        ("value", &|| csr_to_adj(&ir.value_graph)),
        ("macro", &|| csr_to_adj(&ir.macro_graph)),
    ];
    for (name, g) in graphs {
        let adj = g();
        for (src, neighbours) in adj.iter().enumerate() {
            for &dst in neighbours {
                if src >= v || dst >= v {
                    bail!("invariant_solver: dangling edge in {}_graph: {} -> {} (|V|={})", name, src, dst, v);
                }
            }
        }
    }

    let global_adj = global_csr_to_adj(ir);
    for (src, neighbours) in global_adj.iter().enumerate() {
        for &dst in neighbours {
            if src >= v || dst >= v {
                bail!("invariant_solver: dangling edge in graph_csr: {} -> {} (|V|={})", src, dst, v);
            }
        }
    }
    let global_rev_adj = global_csr_rev_to_adj(ir);
    for (src, neighbours) in global_rev_adj.iter().enumerate() {
        for &dst in neighbours {
            if src >= v || dst >= v {
                bail!("invariant_solver: dangling edge in graph_csr_rev: {} -> {} (|V|={})", src, dst, v);
            }
        }
    }

    let name_v = ir.name_graph.vertex_count();
    for src_idx in 0..name_v {
        let src_id = NodeId(src_idx as u32);
        for (dst_id, edge) in ir.name_graph.neighbours(src_id) {
            if *edge != EdgeKind::Renames {
                continue;
            }
            let dst_idx = dst_id.index();
            if src_idx >= v || dst_idx >= v {
                continue;
            }
            let src_kind = &ir.nodes[src_idx].kind;
            let dst_kind = &ir.nodes[dst_idx].kind;
            let src_tag = node_kind_tag(src_kind);
            let dst_tag = node_kind_tag(dst_kind);
            let rename_src_ok = matches!(src_kind, CanonNodeKind::Use { .. } | CanonNodeKind::ExternCrate { .. });
            if !rename_src_ok {
                bail!("invariant_solver: illegal Renames edge {} ({}) -> {} ({}): source must be Use/ExternCrate", src_idx, src_tag, dst_idx, dst_tag);
            }
            let allowed_cross_kind = matches!(src_kind, CanonNodeKind::Use { .. } | CanonNodeKind::ExternCrate { .. });
            if src_tag != dst_tag && !allowed_cross_kind {
                bail!("invariant_solver: illegal Renames edge {} ({}) -> {} ({}): kind mismatch", src_idx, src_tag, dst_idx, dst_tag);
            }
            if allowed_cross_kind && !is_name_bearing(dst_kind) {
                bail!("invariant_solver: illegal Renames edge {} ({}) -> {} ({}): destination is not name-bearing", src_idx, src_tag, dst_idx, dst_tag);
            }
        }
    }

    for (idx, node) in ir.nodes.iter().enumerate() {
        if let CanonNodeKind::Impl { for_ty, .. } = &node.kind {
            let ok = matches!(
                ir.nodes.get(for_ty.0 as usize).map(|n| &n.kind),
                Some(CanonNodeKind::Type { .. }) | Some(CanonNodeKind::Struct { .. }) | Some(CanonNodeKind::Enum { .. }) | Some(CanonNodeKind::Trait { .. }) | Some(CanonNodeKind::TypeAlias { .. })
            );
            if !ok {
                bail!("invariant_solver: Impl node {} references unknown target {:?}", idx, for_ty);
            }
        }
    }

    let mod_v = ir.module_graph.vertex_count();
    if mod_v > 0 {
        let adj = csr_to_adj(&ir.module_graph);
        if topological_sort(&adj).len() != adj.len() {
            bail!("invariant_solver: module_graph contains a cycle");
        }
    }

    Ok(())
}

fn node_kind_tag(kind: &CanonNodeKind) -> &'static str {
    match kind {
        CanonNodeKind::Crate { .. } => "Crate",
        CanonNodeKind::Module { .. } => "Module",
        CanonNodeKind::Struct { .. } => "Struct",
        CanonNodeKind::Enum { .. } => "Enum",
        CanonNodeKind::Trait { .. } => "Trait",
        CanonNodeKind::AssocType { .. } => "AssocType",
        CanonNodeKind::AssocConst { .. } => "AssocConst",
        CanonNodeKind::Impl { .. } => "Impl",
        CanonNodeKind::Fn { .. } => "Fn",
        CanonNodeKind::FnSig { .. } => "FnSig",
        CanonNodeKind::Type { .. } => "Type",
        CanonNodeKind::Field { .. } => "Field",
        CanonNodeKind::Param { .. } => "Param",
        CanonNodeKind::GenericParam { .. } => "GenericParam",
        CanonNodeKind::WherePred { .. } => "WherePred",
        CanonNodeKind::Variant { .. } => "Variant",
        CanonNodeKind::Attr { .. } => "Attr",
        CanonNodeKind::Lifetime { .. } => "Lifetime",
        CanonNodeKind::Const { .. } => "Const",
        CanonNodeKind::Static { .. } => "Static",
        CanonNodeKind::Use { .. } => "Use",
        CanonNodeKind::ExternCrate { .. } => "ExternCrate",
        CanonNodeKind::TypeAlias { .. } => "TypeAlias",
        CanonNodeKind::TypeRef { .. } => "TypeRef",
        CanonNodeKind::MacroCall { .. } => "MacroCall",
        CanonNodeKind::PathRef { .. } => "PathRef",
        CanonNodeKind::Body { .. } => "Body",
        CanonNodeKind::BasicBlock { .. } => "BasicBlock",
        CanonNodeKind::MatchArm { .. } => "MatchArm",
        CanonNodeKind::Pattern { .. } => "Pattern",
        CanonNodeKind::VisPath { .. } => "VisPath",
        CanonNodeKind::Local { .. } => "Local",
    }
}

fn is_name_bearing(kind: &CanonNodeKind) -> bool {
    matches!(
        kind,
        CanonNodeKind::Struct { .. }
            | CanonNodeKind::Enum { .. }
            | CanonNodeKind::Trait { .. }
            | CanonNodeKind::AssocType { .. }
            | CanonNodeKind::AssocConst { .. }
            | CanonNodeKind::Fn { .. }
            | CanonNodeKind::TypeAlias { .. }
            | CanonNodeKind::TypeRef { .. }
            | CanonNodeKind::Const { .. }
            | CanonNodeKind::Static { .. }
            | CanonNodeKind::ExternCrate { .. }
            | CanonNodeKind::Lifetime { .. }
            | CanonNodeKind::GenericParam { .. }
            | CanonNodeKind::Param { .. }
            | CanonNodeKind::Variant { .. }
            | CanonNodeKind::Module { .. }
            | CanonNodeKind::Use { .. }
    )
}

#[cfg(not(feature = "cuda"))]
use crate::solver::csr_to_adj;
#[cfg(feature = "cuda")]
use crate::solver::gpu_algorithms::reachability_gpu;
#[cfg(feature = "cuda")]
use crate::solver::graph_to_csr;
use anyhow::Result;
use canon::node::{flags, CanonNodeKind};
use canon::CanonIR;
#[cfg(not(feature = "cuda"))]
use std::collections::VecDeque;

pub fn solve(ir: &mut CanonIR) -> Result<()> {
    let call_v = ir.call_graph.vertex_count();
    if call_v == 0 {
        return Ok(());
    }

    let roots: Vec<usize> = ir
        .nodes
        .iter()
        .enumerate()
        .filter_map(|(idx, n)| match &n.kind {
            CanonNodeKind::Fn { name_id, flags: f, .. } => {
                let name = ir.lookup_name(*name_id);
                if name == "main" || (*f & flags::PUB) != 0 {
                    Some(idx)
                } else {
                    None
                }
            }
            CanonNodeKind::Crate { .. } => Some(idx),
            _ => None,
        })
        .filter(|&idx| idx < call_v)
        .collect();

    if roots.is_empty() {
        return Ok(());
    }

    let live = {
        #[cfg(feature = "cuda")]
        {
            let csr = graph_to_csr(&ir.call_graph);
            reachability_gpu(&csr, &roots)
        }
        #[cfg(not(feature = "cuda"))]
        {
            let adj = csr_to_adj(&ir.call_graph);
            reachability_mask(&adj, &roots)
        }
    };

    let before = ir.emit_order.len();
    ir.emit_order.retain(|&id| {
        let idx = id.0 as usize;
        match ir.nodes.get(idx).map(|n| &n.kind) {
            Some(CanonNodeKind::Fn { flags: f, .. }) => {
                if idx < live.len() && live[idx] {
                    return true;
                }
                (*f & flags::PUB) != 0
            }
            _ => true,
        }
    });
    let removed = before - ir.emit_order.len();
    if removed > 0 {
        eprintln!("INFO liveness_solver: pruned {} dead function(s) from emit_order", removed);
    }

    Ok(())
}

#[cfg(not(feature = "cuda"))]
fn reachability_mask(adj: &[Vec<usize>], roots: &[usize]) -> Vec<bool> {
    let n = adj.len();
    let mut visited = vec![false; n];
    let mut q = VecDeque::new();
    for &r in roots {
        if r < n && !visited[r] {
            visited[r] = true;
            q.push_back(r);
        }
    }
    while let Some(u) = q.pop_front() {
        for &v in &adj[u] {
            if v < n && !visited[v] {
                visited[v] = true;
                q.push_back(v);
            }
        }
    }
    visited
}

use crate::solver::csr_to_adj;
use algorithms::graph::topological_sort::topological_sort;
use anyhow::{bail, Result};
use canon::node::CanonNodeKind;
use canon::CanonIR;

pub fn solve(ir: &mut CanonIR) -> Result<()> {
    let macro_nodes: Vec<usize> = ir.nodes.iter().filter(|n| matches!(&n.kind, CanonNodeKind::MacroCall { .. })).map(|n| n.id.0 as usize).collect();

    if macro_nodes.is_empty() {
        return Ok(());
    }

    let v = ir.macro_graph.vertex_count();
    if v == 0 {
        return Ok(());
    }

    let adj = csr_to_adj(&ir.macro_graph);
    let order = topological_sort(&adj);
    if order.len() != v {
        bail!("macro_solver: recursive macro expansion cycle detected in G_macro");
    }

    log::info!("macro_solver: {} macro call(s), expansion order is acyclic", macro_nodes.len());
    Ok(())
}

use crate::solver::csr_to_adj;
use algorithms::graph::topological_sort::topological_sort;
use anyhow::Result;
use canon::CanonIR;

pub fn solve(ir: &mut CanonIR) -> Result<()> {
    let v = ir.module_graph.vertex_count();
    if v == 0 {
        return Ok(());
    }

    let adj = csr_to_adj(&ir.module_graph);
    let order = topological_sort(&adj);
    ir.emit_order = order.into_iter().map(|i| canon::node::CanonId(i as u32)).collect();
    Ok(())
}

use crate::solver::{csr_to_adj, to_node_id};
use algorithms::graph::topological_sort::topological_sort;
use anyhow::Result;
use canon::edge::EdgeKind;
use canon::node::CanonNodeKind;
use canon::CanonIR;

pub fn solve(ir: &mut CanonIR) -> Result<()> {
    let v = ir.name_graph.vertex_count();
    if v == 0 {
        return Ok(());
    }

    let adj = csr_to_adj(&ir.name_graph);
    let order = topological_sort(&adj);

    let mut renames: Vec<(usize, String)> = Vec::new();
    for src_idx in &order {
        let src_id = to_node_id(canon::node::CanonId(*src_idx as u32));
        let src_name = node_name(ir, *src_idx);
        if let Some(name) = src_name {
            for (dst_id, edge) in ir.name_graph.neighbours(src_id) {
                if *edge == EdgeKind::Renames {
                    let _ = dst_id;
                    renames.push((*src_idx, name.clone()));
                }
            }
        }
    }

    for (idx, new_name) in renames {
        apply_rename(ir, idx, &new_name);
    }

    Ok(())
}

fn node_name(ir: &CanonIR, idx: usize) -> Option<String> {
    let kind = &ir.nodes.get(idx)?.kind;
    match kind {
        CanonNodeKind::Struct { name_id, .. }
        | CanonNodeKind::Enum { name_id, .. }
        | CanonNodeKind::Trait { name_id, .. }
        | CanonNodeKind::Fn { name_id, .. }
        | CanonNodeKind::TypeRef { name_id }
        | CanonNodeKind::TypeAlias { name_id, .. }
        | CanonNodeKind::Const { name_id, .. }
        | CanonNodeKind::Static { name_id, .. }
        | CanonNodeKind::ExternCrate { name_id, .. }
        | CanonNodeKind::Lifetime { name_id }
        | CanonNodeKind::GenericParam { name_id, .. }
        | CanonNodeKind::Param { name_id, .. }
        | CanonNodeKind::Variant { name_id, .. } => Some(ir.lookup_name(*name_id).to_string()),
        CanonNodeKind::Use { alias, path_id, .. } => {
            if let Some(a) = alias {
                Some(ir.lookup_name(*a).to_string())
            } else {
                Some(ir.lookup_path(*path_id).to_string())
            }
        }
        _ => None,
    }
}

fn apply_rename(ir: &mut CanonIR, idx: usize, new_name: &str) {
    let new_id = ir.intern_name(new_name);
    if let Some(node) = ir.nodes.get_mut(idx) {
        match &mut node.kind {
            CanonNodeKind::Use { alias, .. } => *alias = Some(new_id),
            _ => {
                eprintln!("WARN name_solver: rename edge targeted non-Use node {}, rename ignored", idx);
            }
        }
    }
}

use crate::solver::csr_to_adj;
use algorithms::graph::dfs::dfs;
use anyhow::Result;
use canon::node::CanonNodeKind;
use canon::CanonIR;
use canon::{edge::EdgeKind, id::NodeId};
use std::collections::HashMap;

fn node_name<'a>(ir: &'a CanonIR, kind: &'a CanonNodeKind) -> Option<&'a str> {
    match kind {
        CanonNodeKind::Fn { name_id, .. }
        | CanonNodeKind::Struct { name_id, .. }
        | CanonNodeKind::Enum { name_id, .. }
        | CanonNodeKind::Trait { name_id, .. }
        | CanonNodeKind::TypeAlias { name_id, .. }
        | CanonNodeKind::TypeRef { name_id }
        | CanonNodeKind::Const { name_id, .. }
        | CanonNodeKind::Static { name_id, .. }
        | CanonNodeKind::ExternCrate { name_id, .. }
        | CanonNodeKind::Lifetime { name_id }
        | CanonNodeKind::GenericParam { name_id, .. }
        | CanonNodeKind::Param { name_id, .. }
        | CanonNodeKind::Variant { name_id, .. } => Some(ir.lookup_name(*name_id)),
        CanonNodeKind::Use { alias: Some(alias), .. } => Some(ir.lookup_name(*alias)),
        CanonNodeKind::Use { path_id, alias: None, .. } => Some(ir.lookup_path(*path_id)),
        _ => None,
    }
}

pub fn solve(ir: &CanonIR) -> Result<()> {
    let name_v = ir.name_graph.vertex_count();
    let mod_v = ir.module_graph.vertex_count();
    if name_v == 0 || mod_v == 0 {
        return Ok(());
    }

    let mut resolves_adj: Vec<Vec<usize>> = vec![Vec::new(); name_v];
    for (src_idx, slot) in resolves_adj.iter_mut().enumerate() {
        let src_id = NodeId(src_idx as u32);
        for (dst_id, edge) in ir.name_graph.neighbours(src_id) {
            if *edge == EdgeKind::Resolves {
                slot.push(dst_id.index());
            }
        }
    }

    let mut origin: Vec<usize> = (0..name_v).collect();
    for (start, slot) in origin.iter_mut().enumerate() {
        let chain = dfs(&resolves_adj, start);
        if let Some(&last) = chain.last() {
            *slot = last;
        }
    }

    let fwd = csr_to_adj(&ir.module_graph);
    let mut direct_parents: Vec<Vec<usize>> = vec![Vec::new(); fwd.len().max(ir.nodes.len())];
    let mut inv_mod: Vec<Vec<usize>> = vec![Vec::new(); fwd.len().max(ir.nodes.len())];
    for (src, nbrs) in fwd.iter().enumerate() {
        for &dst in nbrs {
            if dst < direct_parents.len() {
                direct_parents[dst].push(src);
            }
            if dst < inv_mod.len() {
                inv_mod[dst].push(src);
            }
        }
    }

    let containing_module = |start: usize| -> Option<usize> {
        if start >= inv_mod.len() {
            return None;
        }
        let mut stack = vec![start];
        let mut seen = vec![false; inv_mod.len()];
        while let Some(u) = stack.pop() {
            if seen[u] {
                continue;
            }
            seen[u] = true;
            if let Some(CanonNodeKind::Module { .. }) = ir.nodes.get(u).map(|n| &n.kind) {
                return Some(u);
            }
            for &p in &inv_mod[u] {
                if !seen[p] {
                    stack.push(p);
                }
            }
        }
        None
    };

    let mut by_mod_name: HashMap<(usize, String), Vec<usize>> = HashMap::new();
    for idx in 0..ir.nodes.len() {
        if let Some(name) = node_name(ir, &ir.nodes[idx].kind) {
            if let Some(m) = containing_module(idx) {
                by_mod_name.entry((m, name.to_string())).or_default().push(idx);
            }
        }
    }
    for ((m, name), indices) in &by_mod_name {
        if indices.len() > 1 {
            let all_assoc_methods = indices.iter().all(|idx| {
                matches!(ir.nodes.get(*idx).map(|n| &n.kind), Some(CanonNodeKind::Fn { .. }))
                    && direct_parents
                        .get(*idx)
                        .map(|parents| parents.iter().any(|p| matches!(ir.nodes.get(*p).map(|n| &n.kind), Some(CanonNodeKind::Trait { .. }) | Some(CanonNodeKind::Impl { .. }))))
                        .unwrap_or(false)
            });
            if all_assoc_methods {
                continue;
            }
            eprintln!("WARN provenance_solver: name {:?} shadowed in module {} by nodes {:?}", name, m, indices);
        }
    }

    let _ = origin;
    Ok(())
}

use anyhow::{bail, Result};
use canon::node::{CanonId, CanonNodeKind, CfgOp, PrimTy, TypeKind};
use canon::CanonIR;
use std::collections::HashSet;

pub fn solve(ir: &CanonIR) -> Result<()> {
    let live_emit: HashSet<usize> = ir.emit_order.iter().map(|id| id.0 as usize).collect();
    for idx in live_emit {
        let Some(node) = ir.nodes.get(idx) else {
            continue;
        };
        let CanonNodeKind::Fn { name_id, sig_id, body, .. } = &node.kind else {
            continue;
        };
        if fn_sig_returns_unit(ir, *sig_id) {
            continue;
        }
        let Some(body_id) = body else {
            // Declaration-only items (e.g. trait methods without default bodies)
            // are not executable bodies and are outside return-body completeness.
            continue;
        };
        let CanonNodeKind::Body { blocks } = &ir.node(*body_id).kind else {
            bail!("return_solver: non-unit function `{}` (node {}) body is not structural blocks", ir.lookup_name(*name_id), idx);
        };

        let mut ret_write_count = 0usize;
        let mut explicit_return_value = false;
        let mut outgoing: Vec<Vec<usize>> = vec![Vec::new(); blocks.len()];
        let mut block_returnish: Vec<bool> = vec![false; blocks.len()];

        for (bb_idx, bb_id) in blocks.iter().enumerate() {
            let CanonNodeKind::BasicBlock { ops, .. } = &ir.node(*bb_id).kind else {
                continue;
            };
            for op in ops {
                match op {
                    CfgOp::Assign { lhs, .. } => {
                        if local_is_ret(ir, *lhs) {
                            ret_write_count += 1;
                            block_returnish[bb_idx] = true;
                        }
                    }
                    CfgOp::Call { dest: Some(dest), .. } | CfgOp::FieldAccess { dest: Some(dest), .. } | CfgOp::MethodCall { dest: Some(dest), .. } | CfgOp::StructLit { dest: Some(dest), .. } => {
                        if local_is_ret(ir, *dest) {
                            ret_write_count += 1;
                            block_returnish[bb_idx] = true;
                        }
                    }
                    CfgOp::Return(Some(_)) => {
                        explicit_return_value = true;
                        block_returnish[bb_idx] = true;
                    }
                    CfgOp::Match { dest: Some(_) } => {
                        explicit_return_value = true;
                        block_returnish[bb_idx] = true;
                    }
                    CfgOp::Unreachable => {
                        block_returnish[bb_idx] = true;
                    }
                    CfgOp::Goto(target) => {
                        let t = *target as usize;
                        if t < blocks.len() {
                            outgoing[bb_idx].push(t);
                        }
                    }
                    CfgOp::Branch { true_bb, false_bb, .. } => {
                        let t = *true_bb as usize;
                        let f = *false_bb as usize;
                        if t < blocks.len() {
                            outgoing[bb_idx].push(t);
                        }
                        if f < blocks.len() {
                            outgoing[bb_idx].push(f);
                        }
                    }
                    _ => {}
                }
            }
        }

        if !(ret_write_count == 1 || explicit_return_value) {
            bail!(
                "return_solver: non-unit function `{}` (node {}) missing structural return completeness (ret_writes={}, explicit_return_value={})",
                ir.lookup_name(*name_id),
                idx,
                ret_write_count,
                explicit_return_value
            );
        }

        let reachable = reachable_blocks(&outgoing);
        for bb_idx in reachable {
            if outgoing[bb_idx].is_empty() && !block_returnish[bb_idx] {
                bail!("return_solver: non-unit function `{}` (node {}) has terminal block {} without return-producing op", ir.lookup_name(*name_id), idx, bb_idx);
            }
        }
    }
    Ok(())
}

fn fn_sig_returns_unit(ir: &CanonIR, sig_id: CanonId) -> bool {
    let CanonNodeKind::FnSig { ret, .. } = &ir.node(sig_id).kind else {
        return false;
    };
    matches!(&ir.node(*ret).kind, CanonNodeKind::Type { kind: TypeKind::Primitive(PrimTy::Unit) })
}

fn local_is_ret(ir: &CanonIR, id: CanonId) -> bool {
    match &ir.node(id).kind {
        CanonNodeKind::Local { name_id, .. } => ir.lookup_name(*name_id) == "__ret",
        _ => false,
    }
}

fn reachable_blocks(outgoing: &[Vec<usize>]) -> Vec<usize> {
    if outgoing.is_empty() {
        return Vec::new();
    }
    let mut seen = vec![false; outgoing.len()];
    let mut stack = vec![0usize];
    seen[0] = true;
    while let Some(idx) = stack.pop() {
        for &next in &outgoing[idx] {
            if !seen[next] {
                seen[next] = true;
                stack.push(next);
            }
        }
    }
    seen.into_iter().enumerate().filter_map(|(idx, ok)| ok.then_some(idx)).collect()
}

use crate::solver::constraint_solver::{build_problem, is_selected_vector_valid, RenameConstraintProblem};
use algorithms::optimization::beam_search::beam_search;
use anyhow::Result;
use canon::node::CanonNodeKind;
use canon::CanonIR;

const DEFAULT_BEAM_WIDTH: usize = 32;

#[derive(Clone)]
struct SearchState {
    pos: usize,
    selected: Vec<bool>,
    score: i64,
}

pub fn solve(ir: &mut CanonIR) -> Result<()> {
    let problem = build_problem(ir);
    if problem.transforms.is_empty() {
        return Ok(());
    }
    let best = optimize(&problem, DEFAULT_BEAM_WIDTH);
    emit_diag(
        ir,
        &format!(
            "search_optimizer:selected={}/{} beam={}",
            best.len(),
            problem.transforms.len(),
            DEFAULT_BEAM_WIDTH
        ),
    );
    Ok(())
}

pub fn optimize(problem: &RenameConstraintProblem, beam_width: usize) -> Vec<usize> {
    let n = problem.transforms.len();
    if n == 0 {
        return Vec::new();
    }
    let order = if problem.topo_order.len() == n {
        problem.topo_order.clone()
    } else {
        (0..n).collect()
    };

    let conflict_degree = build_conflict_degree(problem, n);
    let dep_out_degree = build_dep_out_degree(problem, n);

    let initial = SearchState {
        pos: 0,
        selected: vec![false; n],
        score: 0,
    };

    let best = beam_search(
        vec![initial],
        beam_width,
        n,
        |state, _level| {
            if state.pos >= n {
                return vec![state.clone()];
            }
            let idx = order[state.pos];
            let mut out = Vec::with_capacity(2);

            let mut skip = state.clone();
            skip.pos += 1;
            out.push(skip);

            let mut take = state.clone();
            take.selected[idx] = true;
            take.pos += 1;
            if is_selected_vector_valid(problem, &take.selected) {
                let quality = 100 - (conflict_degree[idx] as i64 * 10) - (dep_out_degree[idx] as i64 * 5);
                take.score += quality.max(1);
                out.push(take);
            }
            out
        },
        |state| state.score,
    );

    best.map(selected_indices).unwrap_or_default()
}

fn selected_indices(state: SearchState) -> Vec<usize> {
    state
        .selected
        .iter()
        .enumerate()
        .filter_map(|(i, &v)| if v { Some(i) } else { None })
        .collect()
}

fn build_conflict_degree(problem: &RenameConstraintProblem, n: usize) -> Vec<usize> {
    let mut out = vec![0usize; n];
    for &(a, b) in &problem.conflicts {
        out[a] += 1;
        out[b] += 1;
    }
    out
}

fn build_dep_out_degree(problem: &RenameConstraintProblem, n: usize) -> Vec<usize> {
    let mut out = vec![0usize; n];
    for &(a, _) in &problem.dependencies {
        out[a] += 1;
    }
    out
}

fn emit_diag(ir: &mut CanonIR, label: &str) {
    let name_id = ir.intern_name(label);
    let id = ir.push_node(CanonNodeKind::TypeRef { name_id });
    ir.emit_order.push(id);
}

use anyhow::Result;
use canon::node::CanonNodeKind;
use canon::CanonIR;

fn node_sort_key(ir: &CanonIR, kind: &CanonNodeKind) -> (&'static str, String) {
    match kind {
        CanonNodeKind::Crate { name_id, .. } => ("0_crate", ir.lookup_name(*name_id).to_string()),
        CanonNodeKind::Module { path_id, .. } => ("1_module", ir.lookup_path(*path_id).to_string()),
        CanonNodeKind::Use { path_id, .. } => ("2_use", ir.lookup_path(*path_id).to_string()),
        CanonNodeKind::Struct { name_id, .. } => ("3_struct", ir.lookup_name(*name_id).to_string()),
        CanonNodeKind::Trait { name_id, .. } => ("4_trait", ir.lookup_name(*name_id).to_string()),
        CanonNodeKind::TypeAlias { name_id, .. } => ("5_tyalias", ir.lookup_name(*name_id).to_string()),
        CanonNodeKind::Impl { for_ty, for_trait, .. } => ("6_impl", format!("{}__{}", for_ty.0, for_trait.map(|t| t.0).unwrap_or(0))),
        CanonNodeKind::Fn { name_id, .. } => ("7_fn", ir.lookup_name(*name_id).to_string()),
        CanonNodeKind::Enum { name_id, .. } => ("3_enum", ir.lookup_name(*name_id).to_string()),
        CanonNodeKind::Const { name_id, .. } => ("5b_const", ir.lookup_name(*name_id).to_string()),
        CanonNodeKind::Static { name_id, .. } => ("5c_static", ir.lookup_name(*name_id).to_string()),
        CanonNodeKind::MacroCall { path_id, .. } => ("9b_macro", ir.lookup_path(*path_id).to_string()),
        CanonNodeKind::TypeRef { name_id } => ("9_tyref", ir.lookup_name(*name_id).to_string()),
        CanonNodeKind::ExternCrate { name_id, .. } => ("1b_extern", ir.lookup_name(*name_id).to_string()),
        CanonNodeKind::Lifetime { name_id } => ("0b_lifetime", ir.lookup_name(*name_id).to_string()),
        _ => ("z_other", format!("{:?}", kind)),
    }
}

pub fn solve(ir: &mut CanonIR) -> Result<()> {
    if ir.emit_order.is_empty() {
        return Ok(());
    }

    let keyed: std::collections::HashMap<u32, (&'static str, String)> = ir.emit_order.iter().filter_map(|id| ir.nodes.get(id.0 as usize).map(|n| (id.0, node_sort_key(ir, &n.kind)))).collect();

    ir.emit_order.sort_by(|&a, &b| keyed.get(&a.0).cmp(&keyed.get(&b.0)));

    Ok(())
}

use crate::solver::csr_to_adj;
use anyhow::Result;
use canon::edge::EdgeKind;
use canon::id::NodeId;
use canon::node::CanonNodeKind;
use canon::CanonIR;
use std::collections::{HashMap, HashSet};

pub fn solve(ir: &CanonIR) -> Result<()> {
    let mod_v = ir.module_graph.vertex_count();
    if mod_v == 0 {
        return Ok(());
    }

    let trait_methods: HashMap<u32, HashSet<String>> = ir
        .nodes
        .iter()
        .filter_map(|n| {
            if let CanonNodeKind::Trait { methods, .. } = &n.kind {
                let names: HashSet<String> = methods
                    .iter()
                    .filter_map(|m| match &ir.node(*m).kind {
                        CanonNodeKind::Fn { name_id, .. } => Some(ir.lookup_name(*name_id).to_string()),
                        _ => None,
                    })
                    .collect();
                Some((n.id.0, names))
            } else {
                None
            }
        })
        .collect();

    let adj = csr_to_adj(&ir.module_graph);
    let children_of = |idx: usize| -> Vec<usize> {
        if idx < adj.len() {
            adj[idx].clone()
        } else {
            vec![]
        }
    };
    let type_v = ir.type_graph.vertex_count();
    let mut impl_trait_from_graph: HashMap<usize, Vec<u32>> = HashMap::new();
    for src_idx in 0..type_v {
        for (dst_id, edge) in ir.type_graph.neighbours(NodeId(src_idx as u32)) {
            if *edge == EdgeKind::ImplRef {
                impl_trait_from_graph.entry(src_idx).or_default().push(dst_id.0);
            }
        }
    }
    for traits in impl_trait_from_graph.values_mut() {
        traits.sort_unstable();
        traits.dedup();
    }

    for (idx, node) in ir.nodes.iter().enumerate() {
        let CanonNodeKind::Impl { for_trait, .. } = &node.kind else {
            continue;
        };
        let trait_id = match impl_trait_from_graph.get(&idx).and_then(|ids| ids.first()).copied() {
            Some(id) => id,
            None => match for_trait {
                Some(id) => id.0,
                None => continue,
            },
        };
        if impl_trait_from_graph.get(&idx).is_none() && for_trait.is_some() {
            eprintln!("WARN trait_solver: Impl[{}] has for_trait but no ImplRef edge in type_graph", idx);
        }
        if let Some(ids) = impl_trait_from_graph.get(&idx) {
            if ids.len() > 1 {
                eprintln!("WARN trait_solver: Impl[{}] has multiple ImplRef traits {:?}", idx, ids);
            }
            if let Some(field_trait) = for_trait {
                if !ids.contains(&field_trait.0) {
                    eprintln!("WARN trait_solver: Impl[{}] for_trait {:?} mismatches type_graph {:?}", idx, field_trait, ids);
                }
            }
        }

        let required = match trait_methods.get(&trait_id) {
            Some(m) => m,
            None => continue,
        };

        let implemented: HashSet<String> = children_of(idx)
            .iter()
            .filter_map(|&child| match &ir.nodes.get(child)?.kind {
                CanonNodeKind::Fn { name_id, .. } => Some(ir.lookup_name(*name_id).to_string()),
                _ => None,
            })
            .collect();

        let missing: Vec<String> = required.iter().filter(|m| !implemented.contains(*m)).cloned().collect();
        if !missing.is_empty() {
            eprintln!("WARN trait_solver: Impl[{}] for trait {:?} missing methods {:?}", idx, trait_id, missing);
        }
    }

    Ok(())
}

use crate::solver::csr_to_adj;
#[cfg(feature = "cuda")]
use crate::solver::gpu_algorithms::ac3_gpu_apply;
use crate::solver::gpu_algorithms::kosaraju_scc;
#[cfg(feature = "cuda")]
use algorithms::constraints::ac3::{ConstraintGraph, Domain};
use anyhow::Result;
use canon::edge::EdgeKind;
use canon::id::NodeId;
#[cfg(feature = "cuda")]
use canon::ir::TypeKey;
use canon::node::{CanonId, CanonNodeKind, TypeKind};
use canon::CanonIR;
use std::collections::{HashMap, HashSet};

pub fn solve(ir: &mut CanonIR) -> Result<()> {
    let v = ir.type_graph.vertex_count();
    if v == 0 {
        return Ok(());
    }

    let adj = csr_to_adj(&ir.type_graph);
    let sccs = kosaraju_scc(&adj);
    for scc in sccs.iter().filter(|s| s.len() > 1) {
        let _ = scc;
    }

    derive_instantiates_edges(ir);

    #[cfg(feature = "cuda")]
    {
        let (domains, graph, var_to_node) = build_type_constraint_graph(ir);
        if !graph.constraints.is_empty() {
            let pruned = ac3_gpu_apply(&domains, &graph).unwrap_or_else(|| {
                eprintln!("WARN type_solver: ac3_gpu_apply validation failed; skipping pruning");
                domains.clone()
            });
            for (var_idx, dom) in pruned.iter().enumerate() {
                if dom.is_empty() {
                    let node_id = var_to_node.get(var_idx).copied().unwrap_or_default();
                    eprintln!("WARN type_solver: empty type domain for node {}", node_id);
                }
            }
            apply_pruned_type_domains(ir, &pruned, &var_to_node);
        }
    }

    Ok(())
}

#[cfg(feature = "cuda")]
fn build_type_constraint_graph(ir: &CanonIR) -> (Vec<Domain>, ConstraintGraph, Vec<usize>) {
    let v = ir.type_graph.vertex_count();
    let mut type_nodes = Vec::new();
    let mut node_to_var = vec![None; v];
    for idx in 0..v {
        if matches!(ir.nodes.get(idx).map(|n| &n.kind), Some(CanonNodeKind::Type { .. })) {
            node_to_var[idx] = Some(type_nodes.len());
            type_nodes.push(idx);
        }
    }

    let mut concrete_types = Vec::new();
    for &node_idx in &type_nodes {
        let Some(CanonNodeKind::Type { kind }) = ir.nodes.get(node_idx).map(|n| &n.kind) else {
            continue;
        };
        if is_concrete_type(kind) {
            concrete_types.push(node_idx as i32);
        }
    }
    let fallback_domain: Vec<i32> = if concrete_types.is_empty() { type_nodes.iter().map(|&i| i as i32).collect() } else { concrete_types.clone() };

    let mut domains = Vec::with_capacity(type_nodes.len());
    for &node_idx in &type_nodes {
        let Some(CanonNodeKind::Type { kind }) = ir.nodes.get(node_idx).map(|n| &n.kind) else {
            continue;
        };
        let dom = if is_concrete_type(kind) { vec![node_idx as i32] } else { fallback_domain.clone() };
        domains.push(dom);
    }

    let mut graph = ConstraintGraph::default();
    for src in 0..v {
        let Some(src_var) = node_to_var.get(src).and_then(|v| *v) else {
            continue;
        };
        for (dst, edge) in ir.type_graph.neighbours(NodeId(src as u32)) {
            let dst_idx = dst.index();
            let Some(dst_var) = node_to_var.get(dst_idx).and_then(|v| *v) else {
                continue;
            };
            match edge {
                EdgeKind::TypeUnifies | EdgeKind::Instantiates => {
                    graph.add_constraint(src_var, dst_var, |a, b| a == b);
                    graph.add_constraint(dst_var, src_var, |a, b| a == b);
                }
                _ => {}
            }
        }
    }

    (domains, graph, type_nodes)
}

#[cfg(feature = "cuda")]
fn is_concrete_type(kind: &TypeKind) -> bool {
    !matches!(kind, TypeKind::Param(_) | TypeKind::Extern(_) | TypeKind::Unresolved(_) | TypeKind::TypeRef { .. })
}

#[cfg(feature = "cuda")]
fn apply_pruned_type_domains(ir: &mut CanonIR, pruned: &[Domain], var_to_node: &[usize]) {
    for (var_idx, dom) in pruned.iter().enumerate() {
        if dom.len() != 1 {
            continue;
        }
        let resolved_id = dom[0] as u32;
        let Some(&node_idx) = var_to_node.get(var_idx) else {
            continue;
        };
        let Some(node) = ir.nodes.get_mut(node_idx) else {
            continue;
        };
        let CanonNodeKind::Type { kind } = &mut node.kind else {
            continue;
        };
        if matches!(kind, TypeKind::Unresolved(_) | TypeKind::Param(_)) {
            let old_kind = kind.clone();
            *kind = TypeKind::Adt(CanonId(resolved_id));
            if let Some(existing) = ir.type_index.get(&TypeKey(old_kind.clone())) {
                if *existing == CanonId(node_idx as u32) {
                    ir.type_index.remove(&TypeKey(old_kind));
                }
            }
            ir.type_index.insert(TypeKey(kind.clone()), CanonId(node_idx as u32));
        }
    }
}

fn derive_instantiates_edges(ir: &mut CanonIR) {
    let local_type_by_path = collect_local_type_paths(ir);

    let mut existing: HashSet<(u32, u32, &'static str)> = HashSet::new();
    for src in 0..ir.type_graph.vertex_count() {
        for (dst, edge) in ir.type_graph.neighbours(NodeId(src as u32)) {
            if *edge == EdgeKind::Instantiates {
                existing.insert((src as u32, dst.0, "inst"));
            }
        }
    }

    let mut new_edges: Vec<(u32, u32, EdgeKind)> = Vec::new();
    for n in &ir.nodes {
        let (base, args) = match &n.kind {
            CanonNodeKind::Type { kind: TypeKind::Applied { base, args } } => (*base, args),
            _ => continue,
        };

        if let Some(def_id) = resolve_applied_base_def(ir, base, &local_type_by_path) {
            if existing.insert((n.id.0, def_id, "inst")) {
                new_edges.push((n.id.0, def_id, EdgeKind::Instantiates));
            }
        }

        for arg in args {
            let arg_id = arg.0;
            if existing.insert((n.id.0, arg_id, "inst")) {
                new_edges.push((n.id.0, arg_id, EdgeKind::Instantiates));
            }
        }
    }

    if new_edges.is_empty() {
        return;
    }

    let mut all_edges: Vec<(u32, u32, EdgeKind)> = Vec::new();
    for src in 0..ir.type_graph.vertex_count() {
        for (dst, edge) in ir.type_graph.neighbours(NodeId(src as u32)) {
            all_edges.push((src as u32, dst.0, edge.clone()));
        }
    }
    all_edges.extend(new_edges);

    let node_ids: Vec<CanonId> = (0..ir.nodes.len() as u32).map(CanonId).collect();
    ir.type_graph = canon::csr_graph::CsrGraph::from_edges(node_ids, all_edges);
}

fn collect_local_type_paths(ir: &CanonIR) -> HashMap<String, u32> {
    let mut out = HashMap::new();
    for src in 0..ir.module_graph.vertex_count() {
        let Some(CanonNodeKind::Module { path_id, .. }) = ir.nodes.get(src).map(|n| &n.kind) else {
            continue;
        };
        let module_path = ir.lookup_path(*path_id).to_string();
        for (dst_id, edge) in ir.module_graph.neighbours(NodeId(src as u32)) {
            if *edge != EdgeKind::Contains {
                continue;
            }
            let Some(kind) = ir.nodes.get(dst_id.index()).map(|n| &n.kind) else {
                continue;
            };
            let Some(name_id) = (match kind {
                CanonNodeKind::Struct { name_id, .. } | CanonNodeKind::Enum { name_id, .. } | CanonNodeKind::Trait { name_id, .. } | CanonNodeKind::TypeAlias { name_id, .. } => Some(*name_id),
                _ => None,
            }) else {
                continue;
            };
            let full = format!("{module_path}::{}", ir.lookup_name(name_id));
            out.entry(full).or_insert(dst_id.0);
        }
    }
    out
}

fn resolve_applied_base_def(ir: &CanonIR, base: CanonId, local_type_by_path: &HashMap<String, u32>) -> Option<u32> {
    let CanonNodeKind::Type { kind } = &ir.node(base).kind else {
        return None;
    };
    match kind {
        TypeKind::Adt(id) => Some(id.0),
        TypeKind::Extern(path_id) | TypeKind::Unresolved(path_id) => local_type_by_path.get(ir.lookup_path(*path_id)).copied(),
        _ => None,
    }
}

use algorithms::parsing_compilation::type_unification::{unify_types_auto, TypeConstraintGraph};
use anyhow::Result;
use canon::edge::EdgeKind;
use canon::id::NodeId;
use canon::ir::TypeKey;
use canon::node::{CanonId, CanonNodeKind, TypeKind};
use canon::CanonIR;
use std::collections::{HashMap, HashSet};

pub fn solve(ir: &mut CanonIR) -> Result<()> {
    if ir.type_graph.vertex_count() == 0 {
        return Ok(());
    }

    derive_instantiates_edges(ir);

    let (graph, var_to_node) = build_type_equality_graph(ir)?;
    if graph.is_empty() {
        return Ok(());
    }

    let unified = unify_types_auto(&graph).map_err(anyhow::Error::msg)?;
    apply_unified_type_domains(ir, &unified.representative, &var_to_node);
    Ok(())
}

fn build_type_equality_graph(ir: &CanonIR) -> Result<(TypeConstraintGraph, Vec<usize>)> {
    let v = ir.type_graph.vertex_count();
    let mut type_nodes = Vec::new();
    let mut node_to_var = vec![None; v];
    for idx in 0..v {
        if matches!(ir.nodes.get(idx).map(|n| &n.kind), Some(CanonNodeKind::Type { .. })) {
            node_to_var[idx] = Some(type_nodes.len());
            type_nodes.push(idx);
        }
    }

    let mut graph = TypeConstraintGraph::new(type_nodes.len() as u32);
    let mut seen: HashSet<(u32, u32)> = HashSet::new();

    for src in 0..v {
        let Some(src_var) = node_to_var.get(src).and_then(|v| *v) else {
            continue;
        };
        for (dst, edge) in ir.type_graph.neighbours(NodeId(src as u32)) {
            if !matches!(edge, EdgeKind::TypeUnifies | EdgeKind::Instantiates) {
                continue;
            }
            let dst_idx = dst.index();
            let Some(dst_var) = node_to_var.get(dst_idx).and_then(|v| *v) else {
                continue;
            };

            let (a, b) = (src_var as u32, dst_var as u32);
            if seen.insert((a, b)) {
                graph.add_equality(a, b).map_err(anyhow::Error::msg)?;
            }
            if seen.insert((b, a)) {
                graph.add_equality(b, a).map_err(anyhow::Error::msg)?;
            }
        }
    }

    Ok((graph, type_nodes))
}

fn apply_unified_type_domains(ir: &mut CanonIR, representative: &[u32], var_to_node: &[usize]) {
    let mut root_concrete: HashMap<u32, usize> = HashMap::new();

    for (var_idx, &rep) in representative.iter().enumerate() {
        let Some(&node_idx) = var_to_node.get(var_idx) else {
            continue;
        };
        let Some(CanonNodeKind::Type { kind }) = ir.nodes.get(node_idx).map(|n| &n.kind) else {
            continue;
        };
        if is_concrete_type(kind) {
            root_concrete.entry(rep).or_insert(node_idx);
        }
    }

    for (var_idx, &rep) in representative.iter().enumerate() {
        let Some(&node_idx) = var_to_node.get(var_idx) else {
            continue;
        };
        let Some(&resolved_node_idx) = root_concrete.get(&rep) else {
            continue;
        };

        let Some(node) = ir.nodes.get_mut(node_idx) else {
            continue;
        };
        let CanonNodeKind::Type { kind } = &mut node.kind else {
            continue;
        };

        if matches!(kind, TypeKind::Unresolved(_) | TypeKind::Param(_) | TypeKind::TypeRef { .. }) {
            let old_kind = kind.clone();
            *kind = TypeKind::Adt(CanonId(resolved_node_idx as u32));
            if let Some(existing) = ir.type_index.get(&TypeKey(old_kind.clone())) {
                if *existing == CanonId(node_idx as u32) {
                    ir.type_index.remove(&TypeKey(old_kind));
                }
            }
            ir.type_index.insert(TypeKey(kind.clone()), CanonId(node_idx as u32));
        }
    }
}

fn is_concrete_type(kind: &TypeKind) -> bool {
    !matches!(kind, TypeKind::Param(_) | TypeKind::Extern(_) | TypeKind::Unresolved(_) | TypeKind::TypeRef { .. })
}

fn derive_instantiates_edges(ir: &mut CanonIR) {
    let local_type_by_path = collect_local_type_paths(ir);

    let mut existing: HashSet<(u32, u32, &'static str)> = HashSet::new();
    for src in 0..ir.type_graph.vertex_count() {
        for (dst, edge) in ir.type_graph.neighbours(NodeId(src as u32)) {
            if *edge == EdgeKind::Instantiates {
                existing.insert((src as u32, dst.0, "inst"));
            }
        }
    }

    let mut new_edges: Vec<(u32, u32, EdgeKind)> = Vec::new();
    for n in &ir.nodes {
        let (base, args) = match &n.kind {
            CanonNodeKind::Type { kind: TypeKind::Applied { base, args } } => (*base, args),
            _ => continue,
        };

        if let Some(def_id) = resolve_applied_base_def(ir, base, &local_type_by_path) {
            if existing.insert((n.id.0, def_id, "inst")) {
                new_edges.push((n.id.0, def_id, EdgeKind::Instantiates));
            }
        }

        for arg in args {
            let arg_id = arg.0;
            if existing.insert((n.id.0, arg_id, "inst")) {
                new_edges.push((n.id.0, arg_id, EdgeKind::Instantiates));
            }
        }
    }

    if new_edges.is_empty() {
        return;
    }

    let mut all_edges: Vec<(u32, u32, EdgeKind)> = Vec::new();
    for src in 0..ir.type_graph.vertex_count() {
        for (dst, edge) in ir.type_graph.neighbours(NodeId(src as u32)) {
            all_edges.push((src as u32, dst.0, edge.clone()));
        }
    }
    all_edges.extend(new_edges);

    let node_ids: Vec<CanonId> = (0..ir.nodes.len() as u32).map(CanonId).collect();
    ir.type_graph = canon::csr_graph::CsrGraph::from_edges(node_ids, all_edges);
}

fn collect_local_type_paths(ir: &CanonIR) -> HashMap<String, u32> {
    let mut out = HashMap::new();
    for src in 0..ir.module_graph.vertex_count() {
        let Some(CanonNodeKind::Module { path_id, .. }) = ir.nodes.get(src).map(|n| &n.kind) else {
            continue;
        };
        let module_path = ir.lookup_path(*path_id).to_string();
        for (dst_id, edge) in ir.module_graph.neighbours(NodeId(src as u32)) {
            if *edge != EdgeKind::Contains {
                continue;
            }
            let Some(kind) = ir.nodes.get(dst_id.index()).map(|n| &n.kind) else {
                continue;
            };
            let Some(name_id) = (match kind {
                CanonNodeKind::Struct { name_id, .. }
                | CanonNodeKind::Enum { name_id, .. }
                | CanonNodeKind::Trait { name_id, .. }
                | CanonNodeKind::TypeAlias { name_id, .. } => Some(*name_id),
                _ => None,
            }) else {
                continue;
            };
            let full = format!("{module_path}::{}", ir.lookup_name(name_id));
            out.entry(full).or_insert(dst_id.0);
        }
    }
    out
}

fn resolve_applied_base_def(ir: &CanonIR, base: CanonId, local_type_by_path: &HashMap<String, u32>) -> Option<u32> {
    let CanonNodeKind::Type { kind } = &ir.node(base).kind else {
        return None;
    };
    match kind {
        TypeKind::Adt(id) => Some(id.0),
        TypeKind::Extern(path_id) | TypeKind::Unresolved(path_id) => local_type_by_path.get(ir.lookup_path(*path_id)).copied(),
        _ => None,
    }
}

use anyhow::Result;
use canon::id::NodeId;
use canon::node::{flags, CanonNodeKind};
use canon::CanonIR;

pub fn solve(ir: &CanonIR) -> Result<()> {
    if ir.call_graph.vertex_count() == 0 {
        return Ok(());
    }

    let unsafe_set: Vec<bool> = ir
        .nodes
        .iter()
        .map(|n| match &n.kind {
            CanonNodeKind::Fn { flags: f, .. } | CanonNodeKind::Impl { flags: f, .. } | CanonNodeKind::Trait { flags: f, .. } => (*f & flags::UNSAFE) != 0,
            _ => false,
        })
        .collect();

    let v = ir.call_graph.vertex_count().min(ir.nodes.len());

    for caller_idx in 0..v {
        let caller_id = NodeId(caller_idx as u32);
        let caller_unsafe = unsafe_set.get(caller_idx).copied().unwrap_or(false);
        for (callee_id, _) in ir.call_graph.neighbours(caller_id) {
            let callee_unsafe = unsafe_set.get(callee_id.index()).copied().unwrap_or(false);
            if callee_unsafe && !caller_unsafe {
                let caller_name = node_name(ir, caller_idx);
                let callee_name = node_name(ir, callee_id.index());
                log::warn!("unsafe_solver: safe fn `{}` calls unsafe fn `{}` without unsafe block", caller_name, callee_name);
            }
        }
    }

    Ok(())
}

fn node_name(ir: &CanonIR, idx: usize) -> String {
    ir.nodes
        .get(idx)
        .map(|n| match &n.kind {
            CanonNodeKind::Fn { name_id, .. } => ir.lookup_name(*name_id).to_string(),
            _ => format!("node_{}", idx),
        })
        .unwrap_or_else(|| format!("node_{}", idx))
}

use crate::solver::csr_to_adj;
use anyhow::Result;
use canon::node::{CanonId, CanonNodeKind};
use canon::CanonIR;
use canon::{edge::EdgeKind, id::NodeId};
use std::collections::{HashMap, HashSet};

pub fn solve(ir: &mut CanonIR) -> Result<()> {
    let v = ir.module_graph.vertex_count();
    if v == 0 {
        return Ok(());
    }

    let name_v = ir.name_graph.vertex_count();
    if name_v == 0 {
        return Ok(());
    }

    let fwd = csr_to_adj(&ir.module_graph);
    let local_module_roots: HashSet<String> = ir
        .nodes
        .iter()
        .filter_map(|n| {
            if let CanonNodeKind::Module { path_id, .. } = &n.kind {
                ir.lookup_path(*path_id).strip_prefix("crate::").and_then(|rest| rest.split("::").next()).map(|s| s.to_string())
            } else {
                None
            }
        })
        .collect();
    let mut use_parent_module: HashMap<usize, usize> = HashMap::new();
    for (src_idx, neighbours) in fwd.iter().enumerate() {
        for &dst_idx in neighbours {
            if let Some(CanonNodeKind::Use { .. }) = ir.nodes.get(dst_idx).map(|n| &n.kind) {
                use_parent_module.entry(dst_idx).or_insert(src_idx);
            }
        }
    }

    let mut resolves_by_site: HashMap<usize, Vec<usize>> = HashMap::new();
    for src_idx in 0..name_v {
        let src_id = NodeId(src_idx as u32);
        for (dst_id, edge) in ir.name_graph.neighbours(src_id) {
            if *edge == EdgeKind::Resolves || *edge == EdgeKind::Reexports {
                resolves_by_site.entry(src_idx).or_default().push(dst_id.index());
            }
        }
    }

    for (site_idx, defs) in &mut resolves_by_site {
        defs.sort_unstable();
        defs.dedup();
        if let Some(CanonNodeKind::Use { target, .. }) = ir.nodes.get_mut(*site_idx).map(|n| &mut n.kind) {
            *target = if defs.len() == 1 { Some(CanonId(defs[0] as u32)) } else { None };
        }
    }

    for (site_idx, parent_mod) in use_parent_module {
        if resolves_by_site.contains_key(&site_idx) {
            continue;
        }
        if let Some(CanonNodeKind::Use { path_id, .. }) = ir.nodes.get(site_idx).map(|n| &n.kind) {
            let path = ir.lookup_path(*path_id);
            let root = path.split("::").next().unwrap_or("");
            // External imports without local DefId targets are expected.
            // Keep diagnostics for local unresolved imports only.
            if root != "crate" && !local_module_roots.contains(root) {
                continue;
            }
            eprintln!("WARN use_solver: unresolved use at node {} in module {} path {}", site_idx, parent_mod, path);
        } else {
            eprintln!("WARN use_solver: unresolved use-like node {}", site_idx);
        }
    }

    Ok(())
}

use crate::solver::csr_to_adj;
use anyhow::Result;
use canon::node::{flags, CanonNodeKind};
use canon::CanonIR;
use canon::{edge::EdgeKind, id::NodeId};
use std::collections::VecDeque;

pub fn solve(ir: &mut CanonIR) -> Result<()> {
    let n = ir.nodes.len();
    let name_v = ir.name_graph.vertex_count();
    let mod_v = ir.module_graph.vertex_count();
    if name_v == 0 || mod_v == 0 {
        return Ok(());
    }

    let fwd = csr_to_adj(&ir.module_graph);
    let mut inv: Vec<Vec<usize>> = vec![Vec::new(); mod_v.max(n)];
    for (src, nbrs) in fwd.iter().enumerate() {
        for &dst in nbrs {
            if dst < inv.len() {
                inv[dst].push(src);
            }
        }
    }

    let containing_module = |start: usize| -> Option<usize> {
        if start >= inv.len() {
            return None;
        }
        let mut stack = vec![start];
        let mut seen = vec![false; inv.len()];
        while let Some(u) = stack.pop() {
            if seen[u] {
                continue;
            }
            seen[u] = true;
            if let Some(CanonNodeKind::Module { .. }) = ir.nodes.get(u).map(|n| &n.kind) {
                return Some(u);
            }
            for &p in &inv[u] {
                if !seen[p] {
                    stack.push(p);
                }
            }
        }
        None
    };

    let ancestor_or_eq = |a: usize, b: usize| -> bool {
        if a == b {
            return true;
        }
        if a >= fwd.len() {
            return false;
        }
        let reach = reachability_mask(&fwd, &[a]);
        b < reach.len() && reach[b]
    };

    let parent_module = |m: usize| -> Option<usize> { inv.get(m)?.first().copied() };

    let mut warnings: Vec<String> = Vec::new();

    for src_idx in 0..name_v {
        let src_id = NodeId(src_idx as u32);
        for (dst_id, edge) in ir.name_graph.neighbours(src_id) {
            if *edge != EdgeKind::Resolves {
                continue;
            }
            let dst_idx = dst_id.index();
            let vis_flags = visibility_flags(ir.nodes.get(dst_idx).map(|n| &n.kind));

            let ok = if vis_flags & flags::PUB != 0 || vis_flags & flags::PUB_CRATE != 0 {
                true
            } else if vis_flags & flags::PUB_SUPER != 0 {
                if let (Some(sm), Some(dm)) = (containing_module(src_idx), containing_module(dst_idx)) {
                    parent_module(dm).map(|p| ancestor_or_eq(p, sm)).unwrap_or(false)
                } else {
                    false
                }
            } else {
                containing_module(src_idx) == containing_module(dst_idx)
            };

            if !ok {
                warnings.push(format!("visibility_solver: node {} accesses private item {}", src_idx, dst_idx));
            }
        }
    }

    for w in &warnings {
        eprintln!("WARN {}", w);
    }

    Ok(())
}

fn reachability_mask(adj: &[Vec<usize>], roots: &[usize]) -> Vec<bool> {
    let n = adj.len();
    let mut visited = vec![false; n];
    let mut q = VecDeque::new();
    for &r in roots {
        if r < n && !visited[r] {
            visited[r] = true;
            q.push_back(r);
        }
    }
    while let Some(u) = q.pop_front() {
        for &v in &adj[u] {
            if v < n && !visited[v] {
                visited[v] = true;
                q.push_back(v);
            }
        }
    }
    visited
}

fn visibility_flags(kind: Option<&CanonNodeKind>) -> u32 {
    match kind {
        Some(CanonNodeKind::Module { flags, .. }) => *flags,
        Some(CanonNodeKind::Struct { flags, .. }) => *flags,
        Some(CanonNodeKind::Enum { flags, .. }) => *flags,
        Some(CanonNodeKind::Trait { flags, .. }) => *flags,
        Some(CanonNodeKind::Fn { flags, .. }) => *flags,
        Some(CanonNodeKind::Field { flags, .. }) => *flags,
        Some(CanonNodeKind::Param { flags, .. }) => *flags,
        Some(CanonNodeKind::Const { flags, .. }) => *flags,
        Some(CanonNodeKind::Static { flags, .. }) => *flags,
        Some(CanonNodeKind::Use { flags, .. }) => *flags,
        Some(CanonNodeKind::ExternCrate { flags, .. }) => *flags,
        Some(CanonNodeKind::TypeAlias { flags, .. }) => *flags,
        Some(CanonNodeKind::Impl { flags, .. }) => *flags,
        _ => 0,
    }
}
